INSERT INTO `wp_cp_calculated_fields_form_settings` VALUES (1,'Simple Operations','[[{\"name\":\"fieldname5\",\"index\":0,\"title\":\"Simple Sum of two numbers\",\"userhelp\":\"\",\"ftype\":\"fSectionBreak\",\"csslayout\":\"\"},{\"name\":\"fieldname2\",\"index\":1,\"title\":\"First Number\",\"userhelp\":\"\",\"dformat\":\"number\",\"min\":\"\",\"max\":\"\",\"predefined\":\"3\",\"ftype\":\"fnumber\",\"csslayout\":\"\",\"required\":false,\"size\":\"small\",\"formats\":[\"digits\",\"number\"]},{\"name\":\"fieldname6\",\"index\":2,\"title\":\"Second Number\",\"predefined\":\"2\",\"ftype\":\"fnumber\",\"userhelp\":\"\",\"csslayout\":\"\",\"required\":false,\"size\":\"small\",\"min\":\"\",\"max\":\"\",\"dformat\":\"digits\",\"formats\":[\"digits\",\"number\"]},{\"name\":\"fieldname4\",\"index\":3,\"readonly\":true,\"title\":\"Sum\",\"predefined\":\"\",\"userhelp\":\"Note: Sum of First Number + Second Number\",\"eq\":\"fieldname2+fieldname6\",\"ftype\":\"fCalculated\",\"csslayout\":\"\",\"required\":false,\"size\":\"medium\"},{\"name\":\"fieldname7\",\"index\":4,\"title\":\"Sum of selected fields\",\"userhelp\":\"\",\"ftype\":\"fSectionBreak\",\"csslayout\":\"\"},{\"choices\":[\"Item A: $10\",\"Item B: $20\",\"Item C: $40\"],\"choiceSelected\":[true,true,false],\"name\":\"fieldname8\",\"index\":5,\"title\":\"Select/un-select some items\",\"ftype\":\"fcheck\",\"userhelp\":\"\",\"csslayout\":\"\",\"layout\":\"one_column\",\"required\":false},{\"name\":\"fieldname9\",\"index\":6,\"title\":\"Sum of selected items\",\"eq\":\"fieldname8\",\"ftype\":\"fCalculated\",\"userhelp\":\"\",\"csslayout\":\"\",\"predefined\":\"\",\"required\":false,\"size\":\"medium\",\"readonly\":false}],[{\"title\":\"Simple Operations\",\"description\":\"Below you can test two simple and frequent operations.\",\"formlayout\":\"top_aligned\", \"formtemplate\": \"cp_cff_18\"}]]','admin@prime-cleaning-service.local','dev-email@wpengine.local','Contact from the blog...','true',0,'http://prime-cleaning-service.local/','The following contact message has been sent:\n\n<%INFO%>\n\n','text','true','','Confirmation: Message received...','Thank you for your message. We will reply to you as soon as possible.\n\nThis is a copy of the data sent:\n\n<%INFO%>\n\nBest Regards.','text','','','','true','This field is required.','Please enter a valid email address.','Please enter a valid date with this format(mm/dd/yyyy)','Please enter a valid date with this format(dd/mm/yyyy)','Please enter a valid number.','Please enter only digits.','Please enter a value less than or equal to {0}.','Please enter a value greater than or equal to {0}.','Submit','Previous','Next',NULL,'0','no','0','put_your@email_here.com','25','Reservation','USD','EN','production','0','','15','0','','0','0',NULL,1,'false','180','60','5','font-4.ttf','25','35','200','4','ffffff','000000','Please enter a valid captcha code.',NULL,'{\"cv_captcha_method\":\"math\"}',NULL,NULL),(2,'Calculation with Dates','[[{\"name\":\"fieldname1\",\"index\":0,\"title\":\"Check-in\",\"ftype\":\"fdate\",\"userhelp\":\"\",\"csslayout\":\"\",\"predefined\":\"\",\"size\":\"medium\",\"required\":false,\"dformat\":\"mm/dd/yyyy\",\"showDropdown\":false,\"dropdownRange\":\"-10:+10\",\"formats\":[\"mm/dd/yyyy\",\"dd/mm/yyyy\"]},{\"name\":\"fieldname2\",\"index\":1,\"title\":\"Check-out\",\"ftype\":\"fdate\",\"userhelp\":\"\",\"csslayout\":\"\",\"predefined\":\"\",\"size\":\"medium\",\"required\":false,\"dformat\":\"mm/dd/yyyy\",\"showDropdown\":false,\"dropdownRange\":\"-10:+10\",\"formats\":[\"mm/dd/yyyy\",\"dd/mm/yyyy\"]},{\"choices\":[\"Parking - $10\",\"Breakfast - $20\",\"Premium Internet Access - $3\"],\"choiceSelected\":[false,false,false],\"name\":\"fieldname3\",\"index\":2,\"title\":\"Optional Services\",\"ftype\":\"fcheck\",\"userhelp\":\"\",\"csslayout\":\"\",\"layout\":\"one_column\",\"required\":false,\"choicesVal\":[\"10\",\"20\",\"3\"]},{\"name\":\"fieldname4\",\"index\":3,\"title\":\"\",\"userhelp\":\"Note: The cost of the optional services are per each night.\",\"ftype\":\"fSectionBreak\",\"csslayout\":\"\"},{\"name\":\"fieldname5\",\"index\":4,\"title\":\"Total Cost\",\"eq\":\"IF(AND(fieldname2,fieldname1), PREC(abs(fieldname2-fieldname1) * (fieldname3+50),2),\'\')\",\"userhelp\":\"The formula is: (checkout - checkin) * (optionals + base rate)<br />Without the optional services the formula would be: (checkout-checkin) * base rate\",\"ftype\":\"fCalculated\",\"csslayout\":\"\",\"predefined\":\"\",\"required\":false,\"size\":\"medium\",\"readonly\":false}],[{\"title\":\"Calculation with Dates\",\"description\":\"The form below gives a quote for a stay in a hotel based in the check-in date, check-out date and some optional services. The base rate used is $50 per night.\",\"formlayout\":\"top_aligned\", \"formtemplate\": \"cp_cff_18\"}]]','admin@prime-cleaning-service.local','dev-email@wpengine.local','Contact from the blog...','true',0,'http://prime-cleaning-service.local/','The following contact message has been sent:\n\n<%INFO%>\n\n','text','true','','Confirmation: Message received...','Thank you for your message. We will reply to you as soon as possible.\n\nThis is a copy of the data sent:\n\n<%INFO%>\n\nBest Regards.','text','','','','true','This field is required.','Please enter a valid email address.','Please enter a valid date with this format(mm/dd/yyyy)','Please enter a valid date with this format(dd/mm/yyyy)','Please enter a valid number.','Please enter only digits.','Please enter a value less than or equal to {0}.','Please enter a value greater than or equal to {0}.','Submit','Previous','Next',NULL,'0','no','0','put_your@email_here.com','25','Reservation','USD','EN','production','0','','15','0','','0','0',NULL,1,'false','180','60','5','font-4.ttf','25','35','200','4','ffffff','000000','Please enter a valid captcha code.',NULL,'{\"cv_captcha_method\":\"math\"}',NULL,NULL),(3,'Ideal Weight Calculator','[[{\"name\":\"fieldname2\",\"index\":0,\"title\":\"Height\",\"userhelp\":\"In cen