\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"https://openchannels.fm/mistral-lechonk-open-source-windows-tools-and-rethinking-the-internets-platforms/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:136:\"LeChonk’s debut, open-source Windows projects, and Wired’s take on digital control shape today’s tech news and business decisions.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 29 Oct 2026 14:00:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: Post Formats, Bring Back the Fun and Flexibility in Blogging\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565637\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://openchannels.fm/post-formats-bring-back-the-fun-and-flexibility-in-blogging/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:134:\"Bob Dunn and Derek Hanson reflect on blogging, personal writing, and using post formats to shape digital presence beyond social media.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 29 Oct 2026 10:33:32 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"WordPress.org blog: WordPress 7.1.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21896\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"https://wordpress.org/news/2026/10/wordpress-7-1-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5918:\"<p class=\"wp-block-paragraph\">This security release features fixes for multiple issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.4 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.<br />WordPress 7.1.4 is a short-cycle release. The next major release will be <a href=\"https://make.wordpress.org/core/7-2/\">version 7.2</a>, currently planned for December 8th.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-4/\">WordPress 7.1.4 HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people and organizations for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A weakness in the WordPress upgrade process which can lead to remote code execution during the upgrade window, reported by <a href=\"https://www.picussecurity.com/resource/author/umut-bayram\">Umut Bayram</a>.</li>\n\n\n\n<li>A stored XSS with specially crafted block markup, reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Privacy Data Removal Requests can be created in a way that leads to stored XSS, reported by Anthropic.</li>\n\n\n\n<li>Multiple stored XSS issues in the Interactivity API independently discovered by AnC and DatNLQ from VietSunshine Cyber Security, rekter0 and Anas cherni, <a href=\"https://decentsecurity.io/\">Marcel Karlsson (whoismarcel)</a>, and Weston Ruter, Jon Surrell, Alex Concha, and Luis Herranz of the WordPress Security Team.</li>\n\n\n\n<li>A stored denial of service issue in the Interactivity API, reported by Jon Surrell of the WordPress Security Team.</li>\n\n\n\n<li>A stored XSS in Customizer selective refresh, reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>A Stored XSS in the Categories block reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Specially crafted User Logins can lead to a stored XSS reported by Anthropic.</li>\n\n\n\n<li>Unpublished customizer changesets can be discovered by unauthenticated users, reported by <a href=\"https://www.linkedin.com/in/antoniolorensius/\">Antonio Lorensius Silaban</a>.</li>\n\n\n\n<li>A Stored XSS in Playlist and image blocks, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Stored XSS in <code>core/comments-pagination-next</code> and <code>core/comments-pagination-previous</code> blocks, reported by Alex Concha of the WordPress Security Team.</li>\n\n\n\n<li>Notes can be read by privileged users that lack access to edit the post the note is attached to, reported by Ramon of the WordPress Security Team.</li>\n\n\n\n<li>An update to the bundled root certificates due to the eMudhra revocation.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> and <a href=\"https://profiles.wordpress.org/ntsekouras/\">Nik Tsekouras</a>. WordPress 7.1.4 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"is-style-wporg-props-medium wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@darerodz\">David Arenas</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ellatrix\">Ella Van Durpe</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/kirasong/\">Kira Song,</a><a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@mciampini\">Marco Ciampini</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@santosguillamot\">Mario Santos</a>, <a href=\"https://w.org/@mcsf\">Miguel Fonseca</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@umut3806\">umut3806</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes were backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 3 has also been released, containing all applicable fixes.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 17:13:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Aaron Jorbin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:119:\"WPTavern: #239 – Remkus de Vries on How Scanfully 2.0 Is Making WordPress Security and Performance Monitoring Simpler\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209252\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:134:\"https://wptavern.com/podcast/239-remkus-de-vries-on-how-scanfully-2-0-is-making-wordpress-security-and-performance-monitoring-simpler/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:46690:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case how Scanfully 2.0 is making WordPress security and performance monitoring simpler.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Remkus de Vries. Remkus has been active in the WordPress space for over 20 years, starting out with his own agency focused on high performance, scalable WordPress websites. Over time he has diversified into education and community building with projects like WithinWP, and a new initiative, The Guild, which is a paid community aimed at helping people build smarter, more performance, sites through a first principles approach.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our conversation centres on Scanfully, a site health and monitoring SaaS Remkus co-founded, which recently hit version 2.0. Scanfully&#8217;s focus is giving users meaningful, actionable, insights into WordPress site, health, security performance, email, deliverability, DNS, and more. Packing all this data into an easy to understand dashboard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about Remkus&#8217; motivation for diving deep into the complexities of WordPress monitoring, and why many users struggle to keep on top of the technical side of their websites. Remkus argues that too many site owners are stuck in a reactive mode, only investigating issues once something breaks. And Scanfully aims to change that mindset by making ongoing health checks accessible and easy to parse, even for the spreadsheet averse.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Remkus walks us through the products evolution, including the 2.0 update that aimed to reimagine their dashboard experience, added public APIs, and introduced tools like MCP AI integration, empowering users to query their sites health conversationally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into recent and upcoming features such as WooCommerce checkout monitoring, activity logs, and future add-ons designed to cover forms and other business critical flows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you manage multiple WordPress sites, run an agency or are simply interested in building more robust futureproof WordPress projects, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you can find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Remkus de Vries.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m joined on the podcast by Remkus de Vries. Hello, Remkus.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:29] <strong>Remkus:</strong> Hello, Nathan.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:30] <strong>Nathan Wrigley:</strong> It&#8217;s been a while. Remkus and I have been on many calls in the last few days and weeks. We&#8217;re going to have today about a project that Remkus has been actively involved in for a number of years. It&#8217;s called Scanfully. We&#8217;ve reached version, I&#8217;m going to say 2.0, let&#8217;s go with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:46] <strong>Remkus:</strong> Yeah. Yeah. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:47] <strong>Nathan Wrigley:</strong> But over the last few days it&#8217;s actually advanced a little beyond that. So that&#8217;s going to be the main focus.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I would probably urge listeners to this podcast. If you want to understand what the product is and how it works, maybe press pause. Go to Scanfully.com, so scanfully.com, and then come back and you&#8217;ll understand fully what the product is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before we get stuck into updates and product and what it all does. Very briefly, Remkus, do you want to just tell us a little bit about you, your backstory, WordPress space, that kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:17] <strong>Remkus:</strong> Yeah, sure. Been in the WordPress space, active, 20 plus years now. Started with an agency, very quickly moved into complex performance scaling, more complicated type of sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ran a niche agency like that for a very long time. In the last couple of years I&#8217;ve been doing some diversification. I have withinwp, which is a WordPress, how do I explain this? Because this is also in transit, but it&#8217;s a podcast, it&#8217;s a newsletter. One that&#8217;s being cited by This Week in WordPress a lot, I should say.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And part of it is the educational side, which is the part that I&#8217;m building out currently. And what I mean with educational side, that I&#8217;m preparing a community, a paid community, that has the sole goal to help you better understand WordPress and build better sites, smarter sites, more performance sites, that sort of stuff. Basic first principles type approach.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that is roughly how I look at WordPress. And Scanfully is something I started with my co-founder Barry, let&#8217;s call it three years ago. And from a similar angle, we want to solve, essentially site health and performance monitoring tool of your WordPress site in the broadest sense of the word. Meaning the word Scanfully is literal. We scan fully and what we&#8217;re not scanning fully currently, we will be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:32] <strong>Nathan Wrigley:</strong> Okay. Thank you. Can I ask a question? May touch on your personality, I guess. All those years ago, 20 plus years when you came into WordPress. How can you explain why you delved into this bit? Because there were so many ways that you could have gone, but you&#8217;ve really made scanning, and site health, and monitoring and performance, that is your thing. Is there a bit of that which, speaks to you on some level? Do you find yourself drawn in that direction, no matter where you look on the internet?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:58] <strong>Remkus:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:59] <strong>Nathan Wrigley:</strong> Do you enjoy data analytics, spreadsheets, numbers, all of that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:03] <strong>Remkus:</strong> I wouldn&#8217;t call it enjoy, but, I&#8217;ve always been good at it. I always found it fun to some degree. But in general, I get bored quite easily. If I&#8217;m to stick with a topic, it needs to be the complicated version of a topic. To me, in web development, that quickly revolves around all the things that make a WordPress site more tricky to scale, or more tricky to make fast, or more tricky to fill in the blank. There&#8217;s tonnes of different subtopics to that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:25] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:26] <strong>Remkus:</strong> And that then gives you a different view of what is important. And Scanfully is one of the answers to that. we. See that there&#8217;s, I think the whole industry is levelling up in a way. I don&#8217;t think it&#8217;s happening fast enough, but part of it forces you to start thinking about things in a more professional way, like more preemptively understanding what is something that&#8217;s going on. What is a trend on your site? What do you see happening? And I think we&#8217;re still too much on the reactive side of things. So if my side is down, or if somebody complains it&#8217;s slow, then I&#8217;ll have a look. And we want to change that awareness and make it one of your first thoughts instead of an afterthought.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:02] <strong>Nathan Wrigley:</strong> It&#8217;s a curious thing then that the complexity which you enjoy, in a sense, you require other people to not enjoy it as much as you, in order for you to have a product. And I am one of those people. If you present me with a, I don&#8217;t know, a Google Analytics dashboard, or a spreadsheet which goes beyond about four rows, then I quickly lose interest. I genuinely can&#8217;t maintain my effort over there. I glaze over and don&#8217;t enjoy it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so part of the problem with dealing with WordPress is getting over that hump. Maintaining the interest in an area that I feel ill-equipped, not just ill-equipped, completely out of my depth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so having tooling, the likes of which you&#8217;ve built with Scanfully enables people like me to actually stand back and go, okay, that complicated thing is made more easy. I can actually start to understand it in real terms, with data and charts that are less overwhelming. And I guess that&#8217;s the point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:53] <strong>Remkus:</strong> That is the point, and that is essentially also the driver, why we went from dashboard version 1.x to now, 2.x. Because it&#8217;s very easy when you&#8217;re on the more technical side of things and you kind of understand what the signal is and what it&#8217;s implying to forget what the person who doesn&#8217;t understand the extra layers and the assumptions that go underneath. Like what does that actually mean?</p>\n\n\n\n<p class=\"wp-block-paragraph\">The 2.0 rebrand. Because it&#8217;s not a rebrand in terms of what we do, but it&#8217;s a rebrand and how we interpret every single version of the monitoring metrics that we collect, how we present it, and what we allow you to do with it. Everything has been rethought. It&#8217;s been a, I think in total, we&#8217;ve had about four or five months of just working with a redesign. And we call it a redesign because it is, because it visually looks different.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;ve got all this feedback of how people are using it. And a common theme was, we&#8217;re missing this, we&#8217;re missing that. Could you make that easier? So we were like, okay, that&#8217;s a lot of stuff pointing in the same direction. Why don&#8217;t we start rethinking how we&#8217;re going about helping you figure this out?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ll give you a very concrete example. So if a site goes down, because we have an uptime monitoring, you get a notification. But if it&#8217;s the server that goes down and you have 25 sites on that server, it doesn&#8217;t make a lot of sense for you to receive 25 emails.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:05] <strong>Nathan Wrigley:</strong> No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:06] <strong>Remkus:</strong> So gathering information per monitoring alert is something we&#8217;re doing now. And, the same goes for if there&#8217;s, I don&#8217;t know, if the latest plugin you&#8217;re using on all of your sites has something that needs to be fixed, or something that is already fixed. So let&#8217;s assume there&#8217;s a security release for it. You don&#8217;t need to know that 25 emails. You need to know there&#8217;s one email, and these are the sites that are affected. But you also want to know, is this a high risk? Is this a medium risk? Is this a low risk?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because there&#8217;s plenty of security stuff that is so close to impossible to replicate that, do I need to act right now? Maybe, but we give you the insight that you can act upon it. Like it&#8217;s not, we&#8217;re not forcing you to pay all the attention all the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s things like that. So we had the data already, but the question then becomes, how do we make this digestible? How does this become a signal, versus the noise that it&#8217;s also is? So that&#8217;s a lot of rethinking. That&#8217;s a lot of rethinking in what is valuable to share, and how is it valuable to share and what are the things you would like to do with certain things?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, an example, related to that is what if there is an update available for a plugin that you&#8217;re using in a few places? But there&#8217;s no fix yet. Do we need to send you every single day that there is a security update? Or there&#8217;s a security issue? Probably not. So why don&#8217;t we allow you to snooze a particular alert? It&#8217;s simple things like that. And I say simple. It&#8217;s not simple to implement, but.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:27] <strong>Nathan Wrigley:</strong> Simple on the front end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:28] <strong>Remkus:</strong> Yeah. Simple for you as an end user. So that was a lot of thinking and figuring out how do we make this more pleasurable, for as pleasurable as the topic itself is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:39] <strong>Nathan Wrigley:</strong> I&#8217;m going to circle back to the product in a moment, but I&#8217;m going to ask you a curious question.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:43] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:43] <strong>Nathan Wrigley:</strong> You may balk at this question and think, okay, that&#8217;s unusual and a bit weird. Is the WordPress space for you quite an exasperating thing. And what I mean by that is, you are obviously steeped in this knowledge, about how things can go wrong, and how a poor implementation of something over here can have catastrophic effects over there. Given enough time, and the stars aligning in a certain way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know how to describe this. Does that mean that everywhere you look, you just see catastrophe and problems. And you open up a WordPress website, you&#8217;ve got a new client or somebody&#8217;s onboarded you with the plugin. You look inside and you sort of face plant, head slap. Okay. All the stuff that I know, which is second nature to me. Why don&#8217;t they all know this? There&#8217;s no question there, but can you see what I&#8217;m trying to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:27] <strong>Remkus:</strong> Yeah. Yeah, I can. You&#8217;re not recording the video. The people listening didn&#8217;t see me nod along the way of what you were saying, but yes. If you understand things. So there&#8217;s a principle called first principles. Which means everything we approach, we should approach from the first principles. Like what is the base layer of where to solve problems. And, this is not even just WordPress, this is life, I guess.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there&#8217;s a big tendency for people to look at a problem and then have the idea of how they want to fix the problem, but they don&#8217;t actually look at the layer, it should be fixed. They just want to fix the outing. That&#8217;s not really a fix, right. You fix things at the bottom layer. You can identify where the problem lives.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And when that is your view on life slash work. Yeah, there&#8217;s moments where you go, how do you, not look into this? This is your work, this is your job, this is your, competency. Why do you not dive into this? But I also understand that&#8217;s not for everybody to be in that layer of how I look at things. And it&#8217;s not me wanting to force other people, my model of the world, but it is something where I go, you don&#8217;t need to do my model of the world, but there&#8217;s some stuff that you actually should be quite skilled on because it&#8217;s part of your job. Because it touches your job. It touches the clients you serve and all of that sort of stuff. Long-winded answer, but yes, I have those moments.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:39] <strong>Nathan Wrigley:</strong> Yeah, I guess it must be the same no matter which bit of WordPress you&#8217;re in. So for example, I don&#8217;t know if you&#8217;re a front end designer and you see catastrophic use of fonts and spacing and typography, and it would make the head plant moment occur. But also accessibility. And there&#8217;s these tendrils isn&#8217;t there? And we can&#8217;t become expert at all of them, but many of the things are inconveniences. Where if something goes wrong, it&#8217;s annoying, but that&#8217;s probably where it ends.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whereas the stuff that you are dealing with, there&#8217;s a potential for catastrophe to occur. The website gets defaced or taken down, or the server gets compromised and is used in some crazy way that we can&#8217;t imagine. That makes your part I suppose a little bit more essential. But then, as as you said, we can&#8217;t all be experts, and relying on the expertise that you have and the tools that you&#8217;ve built. I suppose that&#8217;s why you occupy the space that you do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:33] <strong>Remkus:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:33] <strong>Nathan Wrigley:</strong> Because not everybody can spend the time becoming as knowledgeable as, as you have become.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:37] <strong>Remkus:</strong> And I, for the record, I don&#8217;t acclaim to have all the knowledge. I just happen to specialise on a few things I find highly interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:44] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:44] <strong>Remkus:</strong> My goal for the Within WordPress community that I want to build, which is called The Guild, is exactly to behave like a guild. We&#8217;re all there to elevate each other up. That is what a guild is supposed to do. And, back in the day, you had guilds that were that you went there, you were part of it, and all that had as a goal was to help you elevate your craft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we need to start thinking about what we do as a craft. And how do you do your craft? Well there&#8217;s tonnes of different ways to do the craft that&#8217;s putting bread on the table. But if you&#8217;re not actively developing yourself to become better at your craft, then what are you doing? You&#8217;re, essentially behind in the first week you start working. And you&#8217;re only playing catch up. And most people have forgotten that they&#8217;re just in the game of playing catch up. Which I think is a shame.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:26] <strong>Nathan Wrigley:</strong> You&#8217;ve alluded from various bits and pieces that you said. You&#8217;ve suggested what Scanfully does. So we have an idea that there&#8217;s charts, and graphs, and information about things that could be going wrong with your website in the background. But we haven&#8217;t really explained what the tool does at its core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So putting the update to one side, if we just examine why you built the tool in the first place, what does it broadly do? And then we can get into what it most recently does and how it&#8217;s been adapted for the 2.x version.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:55] <strong>Remkus:</strong> So Scanfully is about giving you the information so you know what broke on your site, and what changed and what things you need to pay attention to. Anywhere from critical stuff. So vulnerabilities, downtime, to also adjacent critically, are my emails being sent from the site? Does that still work? So we do email monitoring. We do DNS checking.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We do all kinds of site health, like actual site health menu inside of WordPress. We pull in that data so you can see and you can filter for which of my sites are in PHP seven point, whatever still? You can figure that out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you need to do all kinds of filtering on data that is living in all of your WordPress sites. That&#8217;s a pain in the ass to have to click through every single site to figure out what&#8217;s what. And maybe your control panel on your server tells you something, but Scanfully will tell you everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We will tell you how large the uploads folder is. We will tell you, is your certificate about to be renewed, yes or no? Did anything go wrong when that happened? Things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So anything and everything that goes into the bucket of what is site health, what is a healthy site mean? We are monitoring, or we will be monitoring. We still have a very long list of stuff we&#8217;re going to add. But yeah, the goal for Scanfully is to have you be in control of what&#8217;s going on with your site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:19] <strong>Nathan Wrigley:</strong> Ok thank you. I have some follow up questions just to that, so the first one is. Who has been, or who potentially is your ideal customer? So I&#8217;m going to broadly bucket that as, I don&#8217;t know the person who&#8217;s got just one WordPress, or a handful of WordPress websites and they manage that themselves. Are they the kind of people that you are trying to get? And then I&#8217;m going to go into different buckets of enterprise perhaps. Agency level customers. I&#8217;m imagining there&#8217;s some perfect fit there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:42] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:43] <strong>Nathan Wrigley:</strong> And then also I&#8217;m wondering if hosting companies also might be a customer of yours in terms of adding this in, to a deployed website on their platform.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:53] <strong>Remkus:</strong> They are now. One of the features we added, we kind of already had it, but we added publicly now, with Scanfully 2.0 is a public API. Which means if there&#8217;s a public API, anybody can hook into whatever data we have, and display that in their dashboard or website, or wherever they would choose to do so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yes, we cast a broad net, But the goal is for any client that needs to be in control of what&#8217;s going on with their site. But the reality is this is from freelancers to agencies and indeed, hosting type of adjacent companies. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:25] <strong>Nathan Wrigley:</strong> Right. So there&#8217;s a fit across all of those three things that I just mentioned?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:29] <strong>Remkus:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:29] <strong>Nathan Wrigley:</strong> And do you have pricing that reflects that? So in other words, can you buy a single licence, and a multiple licence and a, I don&#8217;t know, an unlimited licence?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:37] <strong>Remkus:</strong> It&#8217;s a flat structure. It&#8217;s 299 a month per site. Simple.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:41] <strong>Nathan Wrigley:</strong> And, in terms of the level of depth of technical understanding that you have to have in order to get the tool working, is this more a case of upload the plugin, activate the plugin, and then there are some sensible defaults? Or do we have to do a tonne of background research to understand what&#8217;s going on? And maybe that&#8217;ll lead us into the 2.0 stuff in a minute.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:59] <strong>Remkus:</strong> There&#8217;s nothing more than installing and activating.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:03] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:03] <strong>Remkus:</strong> And even the activating we have made as frictionless as possible. The only thing you need to do is once the plugin is activated, you click that button that says connect to your Scanfully dashboard, and assuming you&#8217;re already logged in there, clicking that button is all you need to do. There&#8217;s no copying pasting of keys and other weird stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:18] <strong>Nathan Wrigley:</strong> So I presume from what you said earlier, the 2.x, the article that I&#8217;m going to link to in the show notes on the WP Tavern website is about 2.0, but I understand time has passed and probably by the time this episode will be on two point something.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:32] <strong>Remkus:</strong> 2.3.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:33] <strong>Nathan Wrigley:</strong> It would appear that you obviously took a stab at what you thought people would like to see in their dashboards. That&#8217;s one of the things that&#8217;s been updated. How did you adapt that over time then? Because, like we said earlier, getting complicated data to be easy to understand, that is a proper art form. I don&#8217;t think you&#8217;ll probably ever end this journey.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:52] <strong>Remkus:</strong> No. No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:54] <strong>Nathan Wrigley:</strong> You&#8217;ll just be iterating forever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:54] <strong>Remkus:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:54] <strong>Nathan Wrigley:</strong> But is that one of the things that you got feedback on? Okay, it&#8217;s good, but we&#8217;re still confused. Make it simpler to understand. Just describe that side of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:02] <strong>Remkus:</strong> Yeah. So that&#8217;s the part where you go, how do I go from showing noise? Because there&#8217;s a tonne of data that you actually need to be in control of. But how do I make that, easy, digestible?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So one of the solutions we came up with, and that seems to have gone down really well, people like it, is essentially every view on top has the most important things. So we&#8217;ll tell you if there&#8217;s stuff that you need to be updating. We&#8217;ll tell you if email is not being delivered. We&#8217;ll tell you if the percentage of up and down times you&#8217;re having is odd, or requires more investigation. Essentially we&#8217;re helping you figure out the important things per monitor, per view. And then from there, you can deep dive into the data that we collect and figure out things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:46] <strong>Nathan Wrigley:</strong> You&#8217;re moving away from graphs and data first, into more of a human readable summation in a couple of sentences?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:53] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:53] <strong>Nathan Wrigley:</strong> Okay. So you can finally parse what&#8217;s going on. Okay. That&#8217;s good to know. And you said that&#8217;s been well received?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:59] <strong>Remkus:</strong> Yeah, people like it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:00] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:00] <strong>Remkus:</strong> It&#8217;s more straightforward in terms of quickly understanding what&#8217;s going on. That was a big part, and we also wanted to make that information available more easily as well. And what I mean with that is that inside the API you can query this now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But more conveniently, we have an MCP server available as well. So you can connect us to your favourite LLM, your favourite AI and just ask the questions. Like let&#8217;s say you have a bunch of sites for different clients in there, but one client has a specific question. You&#8217;ve labelled them accordingly inside of Scanfully. You can do that now. And then your LLM, you can ask, either ask it to label it, you say these are the domains, labelled them with this client. And then tell me do I have any vulnerabilities? Is email being sent out correctly? Are there any weird DNS changes? What does my uptime look like? And we&#8217;ll tell you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:46] <strong>Nathan Wrigley:</strong> So the API enables you to, I don&#8217;t know, if you&#8217;re an agency owner, you could build a dashboard, for example, for your clients or something like that. So you could put charts and information in a place where your client can go and see it in a way that makes sense for them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:58] <strong>Remkus:</strong> Correct.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:59] <strong>Nathan Wrigley:</strong> But the MCP enables you to kind of have a conversation with the security and the current state of your WordPress website. That&#8217;s so intriguing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:07] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:08] <strong>Nathan Wrigley:</strong> Have you discovered some interesting, quirky things in there? You know, you you ask it a particular thing and a surprising thing came back?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:13] <strong>Remkus:</strong> I got for one of the sites that I have in my account, I got some intermittent email is not being delivered. And I go, why does it turn on and off all the time? What&#8217;s going on here? So I ask it to investigate, look at any commonalities. Look at anything that stands out. And it sure enough came up with something that goes along the lines of there&#8217;s conflicting DNS records. So if there&#8217;s multiple validation records, I was using a transactional email service for that. But their validation system allows you to have old validation DNS records in there as well. And apparently their system picked up both intermittently. How do you figure that out?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:48] <strong>Nathan Wrigley:</strong> With an MCP, it turns out. Yeah. That&#8217;s really interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:50] <strong>Remkus:</strong> Yeah. So it told me, double check the DNS records here, because it looks like, and then I go, okay, let me check that. And I go in, I dive deeper into the dashboard for my transactional email provider. And I go, hold on. This is, okay. I get it now. So let me delete those. I deleted them, and the problem solved.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:07] <strong>Nathan Wrigley:</strong> Does your MCP enable bi-directional things to happen? Or is it basically read only?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:12] <strong>Remkus:</strong> It is read only on the data. It&#8217;s write on, like I said, if you want to create labels and other things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:18] <strong>Nathan Wrigley:</strong> Unharmful stuff is right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:20] <strong>Remkus:</strong> Correct.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:21] <strong>Nathan Wrigley:</strong> Because you are dealing with quite a lot of powerful stuff here, and writing in the wrong direction in a silly way, which let&#8217;s be honest, MCPs enable us to be very silly very quickly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:30] <strong>Remkus:</strong> Yeah. Yeah. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:31] <strong>Nathan Wrigley:</strong> Okay, that&#8217;s good to know. It&#8217;s basically read only.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay. We&#8217;ve got the dashboard updates with more human readable data. We&#8217;ve got the API. We&#8217;ve got the MCP. Anything else in Scanfully 2.x?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:43] <strong>Remkus:</strong> If we include 2.x, the release we did yesterday is 2.3. And in that we have much smarter user activity tracking. Content changes. Not only who did the change, but what is the change, that sort of stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We pull everything out of WordPress into our dashboard. So for instance, we have a full WordPress activity log and in that log, we collect all the things. Whatever happens on your WordPress site, so that&#8217;s a plugin installed, updated, all those things. So now user activity is in there as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s also the things happening to your user. So elevated admin rights given to a user. Was that supposed to happen? An email address change to a administrator is something you would want to know. On a multi-site, if a user gets to have super admin, you&#8217;ll want to have that logged. So things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the 2.0 essentially, which is a week and a half ago, it allowed us to have a whole bunch of other refinements we had essentially lined up. We have a much better foundation to build these things on top of what we now have. So we can move forward much faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:42] <strong>Nathan Wrigley:</strong> We&#8217;ve already agreed pre hitting the record button that there&#8217;s a whole load of stuff which you know is going to occur, but we are not quite ready for public disclosure at the moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One thing that we didn&#8217;t touch on, which I suspect people will be listening to this thinking, okay, hang on a minute. How does it all work in terms of, is there a scanfully.com/whatever login? In other words, do you have a SaaS sort of admin section?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:06] <strong>Remkus:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:06] <strong>Nathan Wrigley:</strong> So the plugin kind of binds to that, because I miss that at the beginning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:11] <strong>Remkus:</strong> Yeah, correct.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:11] <strong>Nathan Wrigley:</strong> We probably should have explained that. So the plugin binds to the SaaS. The SaaS holds the data. And in that way, for example, an agency could have an overview of all the sites that they&#8217;re managing and that kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:23] <strong>Remkus:</strong> And everything that happens on that site that is worthy of tracking and monitoring for. So again, the activity log is a good example. A WordPress activity log should not live inside the WordPress site, period. From a performance standpoint, it makes no sense. Most databases for most hosting companies have issues when you track and sort a, let&#8217;s call it a busy website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So what we do is we asynchronously pull all of that into our dashboard. So if your site goes down for whatever reason, we have a track record of what the last things that were happening on your site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:53] <strong>Nathan Wrigley:</strong> Oh yeah, of course.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:55] <strong>Remkus:</strong> There&#8217;s just an easier way of being in check.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:58] <strong>Nathan Wrigley:</strong> So you&#8217;d log into the SaaS, everything&#8217;s there. So if your site does have some catastrophic failure, then at least you can begin to understand what&#8217;s going on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:06] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:07] <strong>Nathan Wrigley:</strong> And work backwards from there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:08] <strong>Remkus:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:08] <strong>Nathan Wrigley:</strong> I think that&#8217;s probably all the questions that I&#8217;ve got. Is there anything that we didn&#8217;t touch on that you wanted to mention?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:14] <strong>Remkus:</strong> I think what&#8217;s fun to mention is that this whole rewrite allowed us to start building add-ons as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the base monitor service as we have it currently is what Scanfully is. So that&#8217;s Scanfully monitor. But we&#8217;re, and probably by the time this podcast is being aired, I think we will have, the beta available for WooCommerce checkout monitoring.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is essentially an add-on to the base service. And what it does, we fully check everything that goes into, from is the product available in your WooCommerce, website? Can I add it to cart? Can I then go to cart? Can I then start the checkout? Can I fill out the checkout? Can I start the processing of the actual payment. So we don&#8217;t go into the payment itself? So they&#8217;re test orders, so to say.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:59] <strong>Nathan Wrigley:</strong> But the moment right before?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:01] <strong>Remkus:</strong> Yep to the moment, right before. So we&#8217;ll tell you if we can&#8217;t reach the payments provider. We&#8217;ll tell you that, but we can&#8217;t, at this moment in time, do the step beyond that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:09] <strong>Nathan Wrigley:</strong> So how does that work then? Does it literally do that as if it&#8217;s a human being, you know?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:13] <strong>Remkus:</strong> It does.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:14] <strong>Nathan Wrigley:</strong> Is some part of your SaaS kind of opening up a browser somewhere in effect and doing that journey. Finding a product, putting it in the cart, checking the cart, and so on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:21] <strong>Remkus:</strong> And the fun thing is you get to define what that journey looks like. So if you have a custom WooCommerce checkout, or any of the other solutions. We account for that. And you can tell us if it&#8217;s any different from what their default is, or the WooCommerce default.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And from there you get to essentially define the journey. And then the journey is stored as the thing we&#8217;re checking. And we&#8217;re doing this from the external, obviously. So it doesn&#8217;t touch any monetary things. Nothing gets charged, nothing gets booked. And the plugin that is providing the connection to our dashboard, that plugin cleans up whatever test orders were made in that process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:56] <strong>Nathan Wrigley:</strong> Right, okay. So it&#8217;s not 3000 carts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:58] <strong>Remkus:</strong> Yeah, we don&#8217;t, want to do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:00] <strong>Nathan Wrigley:</strong> Do you enable that in other ways as well? for example, I&#8217;m thinking maybe a contact form is incredibly important to somebody&#8217;s business.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:07] <strong>Remkus:</strong> Yep, that&#8217;ll be next.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:08] <strong>Nathan Wrigley:</strong> Is it possible to, outside of WordPress, visit a contact page, fill out the form fields, and then even, I don&#8217;t know, maybe even check on the other side to see if an email landed or something like that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:17] <strong>Remkus:</strong> A part of it we&#8217;ve already solved with the email monitoring, or I should say email deliverability monitoring.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:23] <strong>Nathan Wrigley:</strong> Of course you&#8217;re on the inside there, so you can see whether that got sent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:27] <strong>Remkus:</strong> Yes. But once we&#8217;re fully done with releasing the WooCommerce checkout monitoring, we are going to move to forms next. Because you&#8217;re right, if you have a landing pages, or a critical contact form or whatever, you need to know that that still is working as intended.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:41] <strong>Nathan Wrigley:</strong> So that&#8217;s a roadmap item. To be able to build these custom journeys, starting with WooCommerce, but more or less anything at some point. We want to see if people are going from A to B to C as we&#8217;d hoped.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:52] <strong>Remkus:</strong> Yeah, it&#8217;ll be a separate thing in the sense that WooCommerce will do a lot more than just checking the validity of the form, because that&#8217;s essentially on the WooCommerce side of things, that&#8217;s the checkout form. You fill out the form. And that&#8217;s the most similar to a general form. But yeah, we will build a separate feature inside of Scanfully that allows you to do all the types of monitoring you could possibly imagine you would need to make sure your forms are working the way you design them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:16] <strong>Nathan Wrigley:</strong> Random question just before we end. How exciting do you find this? When you embark on the journey of building a product like this, you know, oh we&#8217;re going to do this thing, me and my friend. We&#8217;re going to do this thing, it&#8217;s going to be brilliant. And then the reality sets in, you know, it&#8217;s difficult, you&#8217;ve got to manage customers and all that kind of stuff. Do you still wake up excited by this?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:32] <strong>Remkus:</strong> Oh yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:33] <strong>Nathan Wrigley:</strong> Obviously you&#8217;re not going to say the opposite. I&#8217;m just wondering if that curiosity still remains and whether or not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:38] <strong>Remkus:</strong> It does, because there&#8217;s just so much more we can still do. And the feedback that we&#8217;re getting is very positive. And especially with this new imagination of how this should be solved with the 2.x reboot I guess is probably the best word. It just excites me on the potentials that we have.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The WooCommerce checkout monitoring is a good example, but there&#8217;s tonnes of other add-ons we have in mind where it just makes sense for you to have the Scanfully monitor as base. But there&#8217;s stuff that we can do more. We&#8217;re already gathering it in one way or another, and just to be super complete with what we&#8217;re presenting. Yeah, that excites me, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:11] <strong>Nathan Wrigley:</strong> Okay, thank you for chatting to me today. Scanfully.com. Go and check it out. Remkus, where are you apart from there? If people want to contact you, are you available on a particular platform, I don&#8217;t know, social media or email or what?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:26] <strong>Remkus:</strong> remk.us</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:28] <strong>Nathan Wrigley:</strong> Nice. Of course you have that domain. Yeah. That&#8217;s lovely. In which case Remkus I will speak to you soon and thank you for chatting to us about Scanfully.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:38] <strong>Remkus:</strong> Thank you for having me.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/remkusdevries/\">Remkus de Vries</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Remkus has been active in the WordPress space for over twenty years, starting out with his own agency focused on high-performance, scalable WordPress websites. Over time, he has diversified into education and community-building with projects like WithinWP and a new initiative, The Guild, which is a paid community aimed at helping people build smarter, more performant sites through a first principles approach.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our conversation centers on Scanfully, a site health and monitoring SaaS Remkus co-founded, which recently hit version 2.0. Scanfully’s focus is giving users meaningful, actionable insights into WordPress site health, security, performance, email deliverability, DNS, and more, packing all this data into an easy to understand dashboard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about Remkus’ motivation for diving deep into the complexities of WordPress monitoring, and why many users struggle to keep on top of the technical side of their websites. Remkus argues that too many site owners are stuck in reactive mode, only investigating issues once something breaks, and Scanfully aims to change that mindset by making ongoing health checks accessible and easy to parse, even for the spreadsheet-averse.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Remkus walks us through the product’s evolution, including the 2.0 update that aimed to reimagine their dashboard experience, added public APIs, and introduced tools like MCP AI integration, empowering users to query their site’s health conversationally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into recent and upcoming features such as WooCommerce checkout monitoring, activity logs, and future add-ons designed to cover forms and other business-critical flows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you manage multiple WordPress sites, run an agency, or are simply interested in building more robust, future-proof WordPress projects, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://scanfully.com\">Scanfully</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://scanfully.com/introducing-scanfully-2-0-a-completely-rebuilt-dashboard/\">Scanfully 2.0 release post</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://withinwp.com\">Within WordPress</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://withinwp.com/the-guild\">The Guild</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://remk.us\">Remkus&#8217; personal website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://x.com/remkusdevries\">Remkus on X</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 14:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"Open Channels FM: Linux Foundation on AI, Denmark’s Open Source Test, and Ben Thompson’s Take on the Internet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565496\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"https://openchannels.fm/linux-foundation-on-ai-denmarks-open-source-test-and-ben-thompsons-take-on-the-internet/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:131:\"AI quickens open source coding, Denmark tests Collabora beyond Microsoft Office, and Ben Thompson reflects on the changing internet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 13:55:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Open Channels FM: When AI Mistakes Have Real-World Costs: Rethinking Delegated Control\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564628\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://openchannels.fm/when-ai-mistakes-have-real-world-costs-rethinking-delegated-control/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:334:\"Advances in AI have opened an entirely new chapter in how we interact with technology. We are moving rapidly from asking questions of digital assistants to handing them the authority to take actions in the real world. This shift brings efficiency and convenience but also introduces a new kind of risk: errors that cost more [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 09:44:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.21 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=250418\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/10/bbpress-2-6-21-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2160:\"<p class=\"wp-block-paragraph\">bbPress 2.6.21 is a security and maintenance release. Everyone running bbPress should update. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens access control across forum feeds, search results, BuddyPress activity, group forums, attachment requests, topic moves, and old topic and reply redirects. Inherited forum passwords now apply consistently when WordPress renders topic and reply content, and Akismet moderation requests now require HTTPS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maintenance fixes improve forum freshness and child-count queries, preserve metadata when database lookups fail, tighten route and user-profile handling, retain original dates and revision content during moderation and editing, and correct the administration reply destination controls. This release also repairs straightforward orphaned list items on WordPress 6.9 and newer, keeps generated bbPress excerpts available without duplicating content, adds the <code>ugc</code> relationship to topic and reply links, and refreshes administration icons for WordPress 7.2 and newer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">bbPress 2.6.21 still requires WordPress 6.0 or newer and PHP 7.2 or newer, and is tested through WordPress 7.2. The database version remains 264, so no database upgrade is required. The <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-21/\">2.6.21 upgrade notes</a> cover compatibility details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These changes are also in the 2.7 development branch, which remains 2.7.0-alpha-4. Thank you to antaloaalonso, arielmeadow, bor0, Clorith, dd32, deborah86, diddledani, lmstearn, netweb, noruzzaman, Otto42, Pebbleontheshore, r-a-y, rollybueno, sbask, shadow043, SirLouen, softglaze, terresquall, tharsheblows, and ton-ha for reports, patches, testing, and review.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.21.zip\">Download bbPress 2.6.21</a> from WordPress.org, or update from your WordPress dashboard.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 22:33:05 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"WordPress.org blog: WordPress 7.2 Beta 2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21890\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-2/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5994:\"<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 2 is ready for download and testing! </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 2</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 2 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta2.zip\">Beta 2 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta2</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 2 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong><strong>December 8, 2026</strong></strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s in WordPress 7.2 Beta 2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For technical details on the issues addressed since Beta 1, see the following links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F21%2F2026..10%2F28%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed 7.2 WordPress Core Trac tickets</a> since October 20, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-21&amp;until=2026-10-28\">7.2 Gutenberg commits</a> since October 20, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Continued Improvements to WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Beta 2 builds on the first beta with additional enhancements, bug fixes, and refinements across the administration experience and developer APIs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Development continues on the <strong>Abilities API</strong>, including content querying, capability requirements, and improvements to schema handling and permissions. New server-side registration capabilities for <strong>DataViews and DataForm</strong> also provide developers with more ways to extend WordPress interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional work includes improvements to REST API flexibility, admin asset loading, and the transition to modern SVG icons throughout WordPress administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/66325\">Trac #66325</a>, <a href=\"https://core.trac.wordpress.org/ticket/66229\">Trac #66229</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">Trac #66343</a>, <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a>, <a href=\"https://core.trac.wordpress.org/ticket/65089\">Trac #65089</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 2 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Second beta takes shape<br />New abilities take root<br />WordPress grows stronger</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/mamaduka/\"><span class=\"mentions-prefix\">@</span>mamaduka</a> for pre-publish review</em>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 15:49:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"Open Channels FM: Open Source Debates AI, GridCraft Challenges Excel, Tesco Eyes Proxmox\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565311\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://openchannels.fm/open-source-debates-ai-gridcraft-challenges-excel-tesco-eyes-proxmox/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:126:\"Reddit’s open source rules, a new Excel alternative, and Tesco considers open virtualization for retail edge infrastructure.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 15:15:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"Open Channels FM: Adapting to Local Client Needs in a Remote Work World\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564786\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/adapting-to-local-client-needs-in-a-remote-work-world/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:104:\"A look at building business trust and reputation by combining local presence with digital communication.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 12:58:49 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"Akismet: Akismet turns 21. Spam isn’t invited.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=285509\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://akismet.com/blog/akismet-turns-21-spam-isnt-invited/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5062:\"<p class=\"wp-block-paragraph\">On October 25, Akismet turns 21. We&#8217;re celebrating with a few new guests: an official Drupal module, a PHP SDK, and another year of improvements to our WordPress plugin. Spam still isn&#8217;t on the list.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Akismet <a href=\"https://ma.tt/2005/10/akismet-stops-spam/\">launched in October 2005</a> to help people spend less time dealing with comment spam and more time enjoying their blogs. The web has changed a lot since then. People build communities, collect inquiries, accept donations, and create applications on all kinds of platforms. Each of those places gives people a way to contribute. It also gives spammers somewhere to try their luck.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Since then, Akismet has blocked over 570 billion pieces of spam. Every one is something a site owner didn&#8217;t have to spend time sorting through. Our birthday wish is to keep making more room for the real people.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"welcome-drupal\">Welcome, Drupal</h3>\n\n\n\n<p class=\"wp-block-paragraph\">This year, we released the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-drupal-module/\">official Akismet Drupal module</a>, built by the team behind Akismet. It brings our spam protection to Drupal comments, contact forms, webforms, and user registrations, with tools for moderators to review submissions and send corrections back to Akismet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;ve continued building on that welcome. The latest release <a href=\"https://akismet.com/blog/akismet-now-supports-drupal-12/\">supports Drupal 12</a> and passes richer bot-detection signals into spam scoring. On Drupal 12, comments and registrations are supported now; contact forms, webforms, and the Key module will follow as those modules become ready for Drupal 12.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For people using the older community module, we also built an <a href=\"https://akismet.com/blog/upgrade-to-the-official-akismet-drupal-module/\">upgrade path to the official module</a> that carries their API key and protection settings across. The migration guide explains the requirements and which settings need attention.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"welcome-php-developers\">Welcome, PHP developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Akismet&#8217;s API has long made it possible to protect sites beyond WordPress. This year&#8217;s <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">official PHP SDK</a> gives developers a first-party client for bringing that protection into their own PHP applications, including projects built with Laravel or Symfony.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The SDK handles the Akismet API integration so developers can focus on their application. It supports checking submissions, reporting spam and legitimate content, and retrieving usage and account information. The official Drupal module uses it too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re building a place where people can post, sign up, or send a message, there&#8217;s a new tool to help you keep the spam out.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"a-familiar-guest-with-a-few-improvements\">A familiar guest, with a few improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress has been with us from the beginning. This year, we kept improving that experience: clearer setup and error messages, accessibility improvements, better detection of automated submissions, and compatibility fixes. You can find the details in the <a href=\"https://wordpress.org/plugins/akismet/#developers\">WordPress plugin release log</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://akismet.com/blog/akismet-v5-7-ready-for-abilities-and-connectors/\">Version 5.7 also added support for Abilities and Connectors</a>, helping Akismet fit into WordPress&#8217;s evolving tools for integrating external services.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"more-room-for-real-people\">More room for real people</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A comment worth replying to. A message from a future customer. A donation to a cause someone cares about. Those are the things we want coming through.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you to everyone who uses Akismet, builds an integration, reports a problem, or helps us improve. You&#8217;ve been part of these 21 years, and you&#8217;re very much invited to the celebration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whether your site runs on <a href=\"https://wordpress.org/plugins/akismet/\">WordPress</a>, <a href=\"https://akismet.com/blog/introducing-the-official-akismet-drupal-module/\">Drupal</a>, or something you&#8217;re building yourself with the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">PHP SDK</a>, there&#8217;s room at the table.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just no room for spam.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/project/akismet_antispam\">Try out the Drupal module today!</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 26 Oct 2026 15:16:26 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Peter Westwood\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:28;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"Open Channels FM: AI in Cybersecurity: Balancing Speed and Human Oversight\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564606\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"https://openchannels.fm/ai-in-cybersecurity-balancing-speed-and-human-oversight/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:249:\"As AI revolutionizes cybersecurity, organizations struggle with rapid vulnerability detection versus slow human remediation. Balancing efficiency and accountability is crucial, as maintaining human oversight prevents potentially catastrophic errors.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 26 Oct 2026 11:35:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:29;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:110:\"Gutenberg Times: A critical PHP fix, WordPress 7.2 Beta 1, Notes in the margin, and more—Weekend Edition 378\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47314\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"https://gutenbergtimes.com/a-critical-php-fix-wordpress-7-2-beta-1-notes-in-the-margin-and-more-weekend-edition-378/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:31285:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before anything else: check which version of PHP your sites run. On October 21, the PHP project <a href=\"https://wordpress.org/news/2026/10/critical-php-security-release/\"><strong>released fixes for two critical vulnerabilities</strong></a>, and they affect any server running a PHP application, not only WordPress. You&#8217;ll find your version under <strong>Tools → Site Health → Info → Server</strong> in your WordPress admin. If you manage your own server and are still on a version older than 8.2, I highly recommend updating. While many hosts have patched older PHP versions that are end of life, it’s best to stay on versions that PHP officially supports.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On a happier note, I&#8217;m back. I was sick for a stretch earlier this month, which is why there was no edition on October 10. Rather than try to cram four weeks into one post, this edition sticks to the last two. Much of what happened in the gap is covered in my October roundup for developers, linked below.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With that, let&#8217;s get down to the latest news.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly neighborhood developer advocate, <img alt=\"🎃\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f383.png\" style=\"height: 1em;\" /><br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#what-s-new-in-playground\">What&#039;s new in Playground?</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The final major release of the year has entered testing. <strong>David Baumwald</strong> announced that <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\"><strong>WordPress 7.2 Beta 1 is ready for download and testing</strong></a>, with the final release set for December 8. Notes move into a margin beside the canvas and pick up emoji reactions. Text shadows and form element styling arrive in the design tools, a new Secrets API gives plugins a standard place to store API keys, and client-side media processing extends to the Media Library. There&#8217;s even an <strong>On This Day</strong> dashboard widget. Not everything made it, though: The Repository reports that <a href=\"https://www.therepository.email/wordpress-7-2-beta-1-out-now-with-secrets-api-and-notes-upgrades-punts-suggestion-mode-to-7-3\"><strong>Notes suggestion mode was punted to 7.3</strong></a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The quickest way to try it is the 7.2 Beta 1 <a href=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\">Playground instance</a>, or <code>wp core update --version=7.2-beta1</code> on a test site. Not on production.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Not sure where to start? <strong>Noruzzaman&#8217;s</strong> <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\"><strong>Help Test WordPress 7.2</strong></a> breaks the release down by area: security, collaboration, admin, blocks and APIs, design, media. It also walks through the different ways to run a beta, from Playground to a staging site on your host, and points you to where feedback goes. The Beta 1 post is clear that testing counts as contributing, whether or not you&#8217;ve done it before.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Your first contribution to WordPress shouldn’t start with installing Git, Node.js, npm, and Docker. That’s the friction the WordPress Contributor Toolkit removes, and <strong>Ryan Welcher</strong> announced <a href=\"https://make.wordpress.org/core/2026/10/23/wordpress-contributor-toolkit-2-0-a-redesigned-app-in-your-language/\"><strong>Contributor Toolkit 2.0, a redesigned app in your language</strong></a>. It’s rebuilt on the WordPress Design System, ships in ten languages, and adds a settings dialog. After you apply a patch, you can revert a single file without losing the patch itself. It’s also about 350 MB smaller, which helps when a whole Contributor Day room downloads it at once.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jorge Costa</strong> shared <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\"><strong>what&#8217;s new in Gutenberg 24.2</strong></a>, and the Notes feature is the big headline. Notes now float in a margin the editor reserves next to the canvas, so you no longer have to choose between reading feedback and keeping the Settings sidebar open. </p>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><img alt=\"Screenshot of the WordPress post editor with notes shown in the margin to the right.\" class=\"has-border-color has-steel-500-border-color wp-image-47316\" height=\"1469\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/10/gutenberg-notes-cropped.webp?resize=2048%2C1469&#038;ssl=1\" style=\"border-width: 1px;\" width=\"2048\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The Navigation block&#8217;s link search now looks through pages, posts, categories, and tags at once. Gallery can sort hand-picked images and tint all of them with a single duotone. And the design tools push continues with about 80 more PRs. Minimum width and height controls, for example, went from five blocks to 40. </p>\n\n\n\n<p class=\"wp-block-paragraph\">For developers, React 19 is now on by default. Test your plugins and themes, and if something breaks, you can switch it off under <strong>Gutenberg → Experiments</strong>. Gutenberg 24.3 RC1 is already out, too, with rich text formatting across blocks, so expect that next week.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the Developer Blog, I put together <a href=\"https://developer.wordpress.org/news/2026/10/whats-new-for-developers-october-2026/\"><strong>What&#8217;s new for developers? (October 2026)</strong></a>, and I tried something different this month. Instead of walking through every aspect of the project, it focuses on the changes I think matter most if you build on WordPress: custom blocks building their own responsive controls, <code>wp_kses()</code> being rebuilt on the HTML API, stroke-based Core icons, and the automated security review for plugin releases. Everything else is linked at the end.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Readers may remember <strong>Chris Zarate&#8217;s</strong> post on moving collaboration to the server from the last edition. <strong>Alec Geatches</strong> follows it up with <a href=\"https://make.wordpress.org/core/2026/10/14/real-time-collaboration-a-guide-to-sync-engines/\"><strong>a guide to the sync engines for real-time collaboration</strong></a>, comparing yjs-server, DE-RTC, and intent-log on their strengths and weaknesses. In every engine, each change goes through WordPress, which confirms who sent it, checks their permissions, and validates it before merging. You can try all three in the experimental <a href=\"https://github.com/WordPress/gutenberg-sync-engines\">Gutenberg Sync Engines</a> plugin. It needs WordPress 7.0+ and the <a href=\"https://wordpress.org/plugins/presence-api/\">Presence API plugin</a>, and it bundles its own copy of Gutenberg, so deactivate the Gutenberg plugin first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Feature Notifications has been quiet since version 0.2.0 shipped in April 2023. <strong>Jonathan Bossenger</strong> is reviving it with a <a href=\"https://make.wordpress.org/core/2026/10/10/feature-notifications-status-update-and-plan-for-0-3-0/\"><strong>status update and plan for 0.3.0</strong></a>, aiming to ship it with WordPress. That would be the project&#8217;s first working MVP: a notifications system that creates, stores, displays, and dismisses notifications. His honest assessment is that the foundations are solid but nothing is wired up end to end yet. He&#8217;s posting <a href=\"https://make.wordpress.org/core/2026/10/23/wp-feature-notifications-weekly-update-2026-10-23/\"><strong>weekly updates</strong></a> if you want to follow along or help.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Benjamin Zekavica</strong> published the <a href=\"https://make.wordpress.org/core/2026/10/19/recap-wordpress-7-1-mary-lou-retrospective/\"><strong>recap of the WordPress 7.1 &#8220;Mary Lou&#8221; retrospective</strong></a>, summarizing what contributors would keep, add, and change for future release squads. If you answered the survey, this is where your feedback landed.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Sticky headers are one of those things you end up fixing on nearly every block theme site. <strong>Jamie Marsland</strong> turned his fix into a free plugin, <a href=\"https://www.pootlepress.com/2026/10/jamies-header-effects-free-sticky-header-plugin/\"><strong>Jamie&#8217;s Header Effects</strong></a>.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The standout is Chameleon mode: as visitors scroll, the header picks up the background color of the section beneath it and flips its text between light and dark to stay readable. There are also frosted-glass, solid, hide-on-scroll, and transparent overlay styles. It finds your header template part on its own, respects prefers-reduced-motion, and lives under <strong>Appearance → Header Effects</strong>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Meta Box&#8217;s custom models no longer have to sit in isolation. A few weeks after moving model creation into the builder, <strong>Lua Nguyen</strong> announced <a href=\"https://metabox.io/custom-model-field/\"><strong>the new Custom Model field</strong></a>, which lets you pick one or more items from a custom model the same way the Post field picks posts. MB Relationships also gains a Model object type, so you can connect models to posts, terms, users, or other models in either direction. Think hotel rooms as a post type with bookings attached from a custom model—no IDs stored by hand.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On WordPress.com, <strong>Ronnie Burt</strong> covers <a href=\"https://wordpress.com/blog/2026/10/15/wordpress-agent-updates/\"><strong>what&#8217;s new with WordPress Agent</strong></a>: it now designs a custom theme from your answers, hands you off to a simplified AI Editor with Preview and Edit tabs, and can install and manage plugins when you ask. The latest <a href=\"https://wordpress.com/blog/2026/10/16/changelog-premium-themes-newsletters/\"><strong>WordPress.com changelog</strong></a> also opens premium themes to every paid plan, starting with Personal.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.woocommerce.com/2026/10/09/woocommerce-11-2-1-release-notes/\"><strong>WooCommerce 11.2.1</strong></a> fixes two regressions: classic checkout on stores that remove address fields with filters, and postcode validation in the Checkout block for Argentina and a few other countries.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;ve ever had to explain to a client why they should move to a block theme, <strong>Simon Cooke</strong> has done the work for you. His Human Made guide on <a href=\"https://humanmade.com/full-site-editing/wordpress-fse-block-theme-explained/\"><strong>how a WordPress block theme is built, and why it matters for enterprise sites</strong></a> walks through each part of a block theme and who owns it, with a side-by-side comparison to classic themes. He&#8217;s clear that moving is a project, not a theme swap. The point he lands on: when design rules live in the theme, a page built by someone who joined last week follows the same rules as one the designer built.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">What if you could point a tool at any static HTML and CSS site and get an editable block theme back, headers and footers included? That&#8217;s the Static Site Importer, and <strong>Chris Huber</strong> of Automattic talks it through with <strong>Nathan Wrigley</strong> on WP Tavern in <a href=\"https://wptavern.com/podcast/238-chris-huber-on-how-static-site-importer-makes-migrating-any-website-to-wordpress-easier-than-ever/\"><strong>episode #238 on making migration to WordPress easier than ever</strong></a>. You&#8217;ll hear how it crawls a site, maps HTML elements to blocks, and handles trickier features like WooCommerce, plus how it fits into the broader Data Liberation effort.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce&#8217;s Purple theme has a new home. <strong>Luigi Teschio</strong> announced that <a href=\"https://developer.woocommerce.com/2026/10/20/purple-monorepo/\"><strong>Purple development moves to the WooCommerce monorepo</strong></a>, as the first theme in its new themes/ directory, so contributions and bug reports go there now. One of the stated reasons is that keeping themes next to the blocks they use makes it easier for contributors, and AI coding tools, to see how templates and patterns use WooCommerce blocks. Nothing changes for existing installs, and Purple still releases on its own schedule. For more background, <strong>Bob Dunn&#8217;s</strong> Do the Woo episode on <a href=\"https://dothewoo.com/2026/10/15/woocommerce-themes-in-2026-woo-goes-purple-commercegurus-talks-performance/\"><strong>WooCommerce themes in 2026</strong></a> covers Purple and theme performance.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-e4a6afc27afe6c6c wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The new <code>@wordpress/ui</code> package will gradually replace <code>@wordpress/components</code>, so how much of an existing plugin can you move over today? <strong>Ryan Welcher</strong> found out live by <a href=\"https://www.youtube.com/watch?v=3MJUEC4PTa4\"><strong>migrating Advanced Query Loop to @wordpress/ui with the Design System MCP</strong></a>. </p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Once your page registers WebMCP tools, those tool definitions are an API, and the consumer is a language model. <strong>Pascal Birchler</strong> built <a href=\"https://pascalbirchler.com/testing-webmcp-with-playwright/\"><strong>playwright-webmcp for testing WebMCP tool surfaces</strong></a>, with linting, Playwright matchers, agent evals, and a site audit CLI. He lists the failure modes that make this tricky: vague descriptions the model ignores, schemas the browser quietly rejects, and two tools on the same page with nearly identical names.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Extension developers no longer need to duplicate a WooCommerce ability just to expose a few extra fields. <strong>Luis Felipe Zaguini</strong> opened a <a href=\"https://developer.woocommerce.com/2026/10/22/extensible-abilities/\"><strong>call for testing extensible abilities for extension fields</strong></a>, an experimental API in WooCommerce 11.3. Extensions can add fields to product, order, and order item reads and writes, register query filters, and refuse a change with a validator before it saves. It&#8217;s off by default, so turn on <strong>Extensible abilities</strong> under <strong>WooCommerce → Settings → Advanced → Features</strong> to try it. The gift wrap example in the post is a good place to start.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\"><strong>What&#8217;s new in Playground?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">The best way to find out what&#8217;s hard about site editing is to watch someone try it. <strong>Jamie Marsland</strong> built <a href=\"https://www.pootlepress.com/2026/10/new-wordpress-user-testing-app-playground-spacefast/\"><strong>a user testing app</strong></a> <strong>for</strong> <a href=\"https://playground-usertest.view.fast/\"><strong>WordPress on Playground and Spacefast</strong></a> to do exactly that. You send a tester a link, and Playground spins up a fresh site in their browser from your existing demo blueprint, with a card of five to seven tasks in the corner. The results page shows how long each task took, who needed the hint, and whether the site actually changed. It&#8217;s also an MCP server, and it&#8217;ll flag a task that gives away the button name.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Two weeks after the MCP Adapter arrived on WordPress.org as a canonical plugin, the AI team got approval to make MCP a default part of WordPress. <strong>Rae Morey</strong> reports on <a href=\"https://www.therepository.email/wordpress-ai-team-moves-to-make-mcp-a-default-part-of-wordpress-with-7-3-floated-as-a-target\"><strong>the move to make MCP a default part of WordPress, with 7.3 floated as a target</strong></a>. That doesn&#8217;t necessarily mean merging the adapter into Core: bundling it, enabling it through existing interfaces, and building specific capabilities into Core are all on the table. It&#8217;s also a reversal of the reasoning behind the canonical plugin, and maintainers are asking what changed. The <a href=\"https://make.wordpress.org/ai/2026/10/22/ai-contributor-weekly-summary-21-october-2026/\"><strong>AI contributor summary for October 21</strong></a> has the meeting&#8217;s side of the discussion.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Andy Peatling</strong> launched <a href=\"https://wpab.view.fast/\"><strong>WordPress Agent Benchmarks</strong></a> to measure how AI agents handle WordPress, and <strong>Rae Morey</strong> walks through <a href=\"https://www.therepository.email/new-benchmarks-find-ai-agents-overlook-wordpress-and-cant-complete-tasks-via-the-official-mcp-adapter\"><strong>the first results</strong></a>. Across 193 sites built for requests that suited WordPress, agents chose it zero times, even though they named it as an option about half the time. Using the MCP Adapter alone, they completed no tasks on existing sites, largely because it doesn&#8217;t yet bundle the abilities for common operations. <strong>Brian Coords</strong> asks what WordPress would have to change in <a href=\"https://www.briancoords.com/helping-agents-choose-wordpress-w-the-wp-minute/\"><strong>helping agents choose WordPress</strong></a>, drawing on a WP Minute panel with Andy.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Is the MCP Adapter safe? <strong>Brad Williams</strong> of WebDevStudios calls it a door: &#8220;You decide which rooms it opens into.&#8221; He explains why <a href=\"https://webdevstudios.com/2026/10/15/wordpress-mcp-adapter-production/\"><strong>production use of the MCP Adapter is a governance decision</strong></a>, not a plugin decision. An agent gets whatever abilities are exposed, using the permissions of the user it connects as, and every plugin you install can add more. His advice is to write the agent&#8217;s job description before you hand over the keys.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">If you connect an AI client to WooCommerce, this one needs action before you upgrade. <strong>Darren Ethier</strong> explains that <a href=\"https://developer.woocommerce.com/2026/10/21/woocommerce-11-3-mcp/\"><strong>WooCommerce 11.3 removes its deprecated MCP endpoint</strong></a>. Requests to /wp-json/woocommerce/mcp will return a 410. Install the MCP Adapter, create an application password for a user with only the capabilities the client needs, and point the client at the adapter&#8217;s default server. Extensions that hooked into the old endpoint&#8217;s filters should check the post&#8217;s full list of what&#8217;s been removed.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WPShout&#8217;s guide on <a href=\"https://wpshout.com/connect-claude-to-wordpress/\"><strong>how to connect Claude to WordPress</strong></a> opens with the question most guides skip: where your site is hosted decides which route you take. WordPress.com, Jetpack, and other self-hosted sites each get their own path, and the walkthrough uses a free MCP plugin with a least-privilege grant. It&#8217;s also candid about a gap: the WordPress MCP Adapter has no OAuth server of its own, so claude.ai&#8217;s sign-in can&#8217;t connect to it directly yet.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Post revisions spent years bloating databases. Human Made thinks they&#8217;re about to become valuable. In <a href=\"https://humanmade.com/word-on-the-future/agentic-wordpress-revisions-process-mining/\"><strong>WordPress revisions: agentic gold?</strong></a>, <strong>Noel</strong> argues that every revision records what changed, who changed it, and when, which makes them a log of how your team really works. Mine them for repeated changes and you&#8217;ve found the workflows an agent could take over. The post includes a prompt you can run, on a copy of your database and never on production.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-cbdc3ef1b9587f24 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-482e7d690801b7ab wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 24 Oct 2026 16:18:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:30;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Navigating the Value of Friction in a Fast-Paced World\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564568\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://openchannels.fm/navigating-the-value-of-friction-in-a-fast-paced-world/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:249:\"As technology advances, prioritizing speed and convenience can undermine critical engagement and reflection. While automating tasks may enhance efficiency, it risks diminishing the unique value individuals bring to understanding and decision-making.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 23 Oct 2026 16:17:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:31;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"Open Channels FM: Faster Security with Anthropic AI, But Open Source Needs Real Human and Corporate Support\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564542\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"https://openchannels.fm/faster-security-with-anthropic-ai-but-open-source-needs-real-human-and-corporate-support/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:137:\"Faster security scans reveal new software issues yet patching and project upkeep require committed maintainers and company contributions.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 23 Oct 2026 14:05:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:32;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"Open Channels FM: Game Porting and Software Creation Accelerate with AI and OpenAI Concerns\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564498\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://openchannels.fm/game-porting-and-software-creation-accelerate-with-ai-and-openai-concerns/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"Shifting barriers in tech reveal new questions about trust, safety, and sustainability in software.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 22 Oct 2026 14:08:12 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:33;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: Balancing Digital Life While Making the Internet Weird Again\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564472\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openchannels.fm/balancing-digital-life-while-making-the-internet-weird-again/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"Bowe Frankema shares how digital creation affects daily life and what bringing weirdness back to the internet means.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 22 Oct 2026 12:08:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:34;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"Open Channels FM: Munich Bets on Open Source as Meta Apple and NVIDIA Drive Local AI and Hardware Choices\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564438\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"https://openchannels.fm/munich-bets-on-open-source-as-meta-apple-and-nvidia-drive-local-ai-and-hardware-choices/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"Munich’s shift to practical open source, Meta and Apple’s AI partnership, and NVIDIA’s hardware-driven open AI models\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:35;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"WordPress.org blog: Critical PHP Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21835\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://wordpress.org/news/2026/10/critical-php-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2398:\"<p class=\"wp-block-paragraph\"><a href=\"https://www.php.net/archive/2026.php#2026-10-21-5\">The PHP project has announced a security release that fixes two critical security vulnerabilities discovered in PHP</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Due to the critical severity of the issues, site owners are encouraged to immediately update their installations of PHP. Your web host may already be working to update PHP and put web application firewall (WAF) rules in place to mitigate the vulnerabilities, but you should still check for updates from your web host and, if necessary, update PHP as soon as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Within WordPress, you can see which version of PHP your site runs under Tools &gt; Site Health &gt; Info &gt; Server. Many web hosts provide this information in your web hosting administration panel too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These vulnerabilities are <em>not</em> specific to WordPress and affect any server that hosts a PHP application. No WordPress update is required or planned for these issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Versions of PHP prior to 8.2 no longer receive security updates from the PHP project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If your site runs a version prior to this and you manage your own web hosting, you should <em>consider taking your server offline</em> while you prepare to update to a newer version of PHP. This advice is being published by several national cyber security agencies. To quote <a href=\"https://www.ncsc.gov.uk/news/critical-security-issue-affecting-php\">the UK National Cyber Security Centre</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Where immediate remediation is not feasible, organisations should consider taking the system offline until it can be fully mitigated.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Further information on wordpress.org:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/support/update-php/\">Get a faster, more secure website: update PHP today</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/handbook/references/php-compatibility-and-wordpress-versions/\">PHP Compatibility and WordPress Versions</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/documentation/article/faq-my-site-was-hacked/\">FAQ My site was hacked</a></li>\n</ul>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 13:44:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:36;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"WPTavern: #238 – Chris Huber on How Static Site Importer Makes Migrating Any Website to WordPress Easier Than Ever\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209164\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:131:\"https://wptavern.com/podcast/238-chris-huber-on-how-static-site-importer-makes-migrating-any-website-to-wordpress-easier-than-ever/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:48687:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, how the Static Site Importer makes migrating any website to WordPress easier than ever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Chris Huber. Chris&#8217;s journey with WordPress began in his college days, first as a writer and blogger, and eventually progressing to software engineering after moving his personal site, extrachill.com to WordPress in 2018, Chris went deeply into WordPress, developing custom plugins and exploring all the corners of the platform. His passion for experimentation and creative tech led him to Automattic where he now helps shape the WordPress experience as a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our discussion centres around two main topics, Data Liberation and the Static Site Importer tool.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We focus upon the evolving landscape of website migration and ownership. Chris explains how Data Liberation aims to make it easier for users to take control of their sites, whether they&#8217;re moving to WordPress from platforms like Wix, Squarespace, or Drupal, or just want portability for their data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into the Static Site Importer, which takes this a step further by converting any static HTML / CSS website into a fully editable WordPress block theme, headers, footers, and all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris walks us through how these tools work in tandem, highlighting the mechanics behind website crawling, mapping HTML elements to Gutenberg blocks, and handling complex features like WooCommerce and calendars.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the continuous improvement of these tools, how each migration helps raise the bar for future imports, and how this project could fundamentally change the way people move websites between platforms.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re curious about the future of website migration, and how WordPress is removing the hurdles for users who want to truly own and manage their content, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Chris Huber.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Chris Huber. Hello, Chris.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:21] <strong>Chris Huber:</strong> Hey Nathan. Thanks for having me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:22] <strong>Nathan Wrigley:</strong> Yeah, very welcome. Chris and I have never spoken before, but we&#8217;re going to be talking today about two things, data liberation, but also a tool that I&#8217;ve never used, but sounds really interesting. It&#8217;s called the Static Site Importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As is always the case, if you go to wptavern.com and search for the episode with Chris in it, you&#8217;ll be able to find all of the necessary links. In this case, it&#8217;ll be, GitHub pages and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But before we get stuck into it, Chris, would you mind just telling us a little bit about yourself, your background with WordPress, who you work for, that kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:54] <strong>Chris Huber:</strong> So I&#8217;m Chris. I live in South Carolina. My background with WordPress is I started my own blog back when I was in college, that was 2011. But I wasn&#8217;t on WordPress at the time. I switched to WordPress around 2018, and I started getting more and more into it over the years. Now I work for Automattic as of about six months ago. And I&#8217;m a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:14] <strong>Nathan Wrigley:</strong> Thank you. So before those six months, a lot of people in the WordPress space have this, I think, desire to end up at a place like Automattic where they can fully work just on WordPress. That&#8217;s my estimation anyway sometimes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:26] <strong>Chris Huber:</strong> Definitely a dream job. I really love working on WordPress, and it&#8217;s super cool to be able to work at Automattic but I got into software engineering a little bit later in my WordPress career. I was more of a writer and a blogger at first, and over time my website started getting more advanced and I wanted to build more things on it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I got, I was an early adopter to AI, and I started learning a lot. Like as soon as I picked up AI, I started asking a lot of questions and turned my website, my personal WordPress site is called extrachill.com, and it&#8217;s kind of a WordPress multi-site like application with 60 custom plugins on it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I just, I just went crazy. That&#8217;s how I ended up at Automattic is because my website, some things I built on my website were like, attention on Twitter from some people who have been around WordPress for a good bit of time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:15] <strong>Nathan Wrigley:</strong> Yeah, I&#8217;ve noticed this trend. I think there&#8217;s a trend in upper management. Let&#8217;s go for that phrase, for the more curious bits. The unusual, the interesting, the weird and the wonderful. I think there&#8217;s a bit of a movement right now to see that again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Back in the day, I have grey hair, I am considerably older than you, I think Chris. And, when the internet began, I was old enough to be able to use a computer. The internet was a truly strange place. Nobody had the faintest idea what to do with it. And so everybody launched their crazy, unusual thing, and it was normal. And then everything became a bit of a homogenised version of the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These social media platforms came along and normalised everything. And UIs settled down and UXs settled down, and got stuck in a rut. But now there does feel, especially in the WordPress space, as if there&#8217;s a desire create the unusual, and the weird and the wonderful, and that&#8217;s brilliant. That sounds like you&#8217;ve been hired to do just that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What we&#8217;re going to talk about today is not that weird. It&#8217;s fairly useful though, I would say. And, there&#8217;s two parts to it. As I mentioned at the top of the show, there&#8217;s the data liberation part, and then there&#8217;s the static sighting importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think we&#8217;ll go through them in turn, if that&#8217;s all right? Starting with the Data liberation. This was a phrase that I used to trot out a couple of years ago when the Data Liberation project began.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you want to just run and tell us what the Data Liberation Project is, what its goals are?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:42] <strong>Chris Huber:</strong> So the Daily Liberation Project has been ongoing since way before I started working on it. And it is basically, a lot of proprietary website building platforms make it really hard to get off of these platforms. Especially if you want to keep your website design. And that&#8217;s their business model is, they&#8217;re not open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So for a long time we have assumed that Data Liberation meant using WordPress. But recently we have changed that definition a little bit, and it just means turning any website into a portable copy that you can download, and do whatever you would like with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the data Liberation Agent that we have created actually can convert any URL into a portable copy. So you just give it a URL and it loads the site in a browser, and downloads every single page as a perfect copy with all the animations and everything. The only thing it doesn&#8217;t get is anything that&#8217;s inside the database, inside the site. Because it&#8217;s all happening on the outside of the site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that&#8217;s step one to our process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:42] <strong>Nathan Wrigley:</strong> I think that&#8217;s great. I remember it being couched in terms of trying to onboard people from going to use the word rival, although that&#8217;s the wrong word, rival CMSs. So for example, Drupal and Joomla and things like that. The idea being that its really hard work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It can be a lot of work getting a site from over there, Drupal, let&#8217;s say, and bringing it over to WordPress. And so there was an endeavour to make it point and clickable. And in, in the way that you&#8217;ve described it, all that you have to do really to get a fairly functional version of your website is to know the URL.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you go to the original domain, you paste in the URL, some magical voodoo goes on in the background. And within a few moments, that site has been replicated, and hopefully it can then be migrated over to WordPress. But I suppose it goes a little bit further than that because it&#8217;s a two-way promise, isn&#8217;t it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s not just that you can bring things into WordPress. The promise is that should you become fed up of WordPress, you could go in the other direction. You could go WordPress to Drupal. Or indeed you could go WordPress, WordPress. So you could use it as a migration tool or something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it isn&#8217;t just this importing mechanism, it really is liberation in the strictest sense of the word. It&#8217;s your data. Pick it up from wherever it is now. Take it to wherever the heck you want it to go, and we&#8217;ll enable you to do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:01] <strong>Chris Huber:</strong> Yeah, basically. Not even just Drupal, but places like Wix and Squarespace and Weebly and other website building platforms that might be proprietary and open source. Yeah, that&#8217;s step one to the process that we&#8217;re using.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:13] <strong>Nathan Wrigley:</strong> Okay, is there anything technical that we need to know about how that process works before we move on to the Static Site Importer? Or are the two things bound so that if we move on, it&#8217;ll all make sense in due course.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:24] <strong>Chris Huber:</strong> It will all make sense I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:25] <strong>Nathan Wrigley:</strong> Yeah. I&#8217;ll interrupt as I see fit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the next part of this jigsaw puzzle, now that we&#8217;ve got the data liberation piece under control is the Static Site Importer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, this to me at least is new. I had not seen it. I caught a post by a colleague of yours, on maybe it was X or something like that. And I saw it and I thought, okay, that&#8217;s interesting. Static Site Importer, what does that mean? And I dug a little bit deeper, and that&#8217;s why you are on the podcast to explain it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, 10,000 mile view looking down, what&#8217;s the goal of the project? And then I suppose we can get into how it does it and all of that magical stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:59] <strong>Chris Huber:</strong> So the goal of the project is to create WordPress Block Themes from a static HTML website. So any basic HTML, CSS, JavaScript website, converting it into a WordPress site, with the click of a button. So that&#8217;s the basic goal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:15] <strong>Nathan Wrigley:</strong> Okay, so the idea here is that you see a website somewhere online, hopefully it&#8217;s yours. And then you take the URL, but rather than the sort of more generic approach that we just described with Data Liberation, this is then binding it into, you said theme. I&#8217;m going to go with blocks in my definition here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For example, where there&#8217;s a paragraph. Inside the block editor, we would see a paragraph block. And if it was an image, we&#8217;d see an image block. And I guess if there was something on the left and something on the right, we&#8217;d see a, I don&#8217;t know, a group block or something like that. And the design would trickle down from there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The tool itself would make assumptions based upon what it, I&#8217;m doing air quotes, sees. And then it would build it inside the block editor. But curiously, you said theme, so is it also building a theme in the background to take care of all the other, I don&#8217;t know, the headers and the footers and all of that kind of stuff as well?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:10] <strong>Chris Huber:</strong> Yeah, it is materialising an entire WordPress site from scratch. So the importer does take a URL, but how we&#8217;re using it in our tools is we are combining it with data liberation first.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So data liberation gives us that clean copy of the website. So the URL actually goes through data liberation, and then we take the portable copy created by data liberation, and import the whole entire website into WordPress. And it turns this static website into a WordPress site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s not just about URLs. It&#8217;s also about like AI generated websites that you might have on your computer that you might have generated with Claude or Codex. And you want to use it on WordPress. It&#8217;s traditionally been pretty hard to get a high quality block theme from an AI agent without a lot of iteration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So this kind of sidesteps that need to iterate on the block theme, and pull your hair out with the AI who doesn&#8217;t understand so much about how to create a good block theme. And you just don&#8217;t bother with that, and you just convert it into a block theme on its own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The point of it really is removing the responsibility from the AI to create the block theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:14] <strong>Nathan Wrigley:</strong> Okay. So the way that you described it, it sounded like, forgive forgive me if I&#8217;ve misunderstood this. It sounded like you use the tool, and we&#8217;ll get into how that works properly in a minute. You use the tool. You paste in a URL, that could be a locally hosted website, or it could be something out in the wild on the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then the data liberation part of it spins up. And then it sounds like there&#8217;s a blob of data somewhere, which the data liberation tool finally exports. So it does its bits. This blob of data is then consumed, and we can discuss what that is. Is that a plugin? How does that even work?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then once it&#8217;s parsed that blob of data, then it can figure out, okay, this part belongs in the header, this part belongs in the footer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This part is the main content area, this is the homepage. And so on. How does it do that? How does it shatter out particular URLs? Like this is the about us page. Or do you have to do it page by page? About, home, archive? How does it do all that? Is it literally one URL and it goes around and spiders the whole thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:13] <strong>Chris Huber:</strong> It crawls every page on the website, the data liberation part does. But I think of the importer almost like a giant funnel and like a sorting mechanism. And it&#8217;s very much mapped to Core, WordPress Core. So I built the whole thing&#8217;s built with AI and just basically like over time mapping different elements on the page to Gutenberg, while having the AI read Gutenberg Core directly, and read the source and make its own mappings.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the whole thing is just a series of import, a website, see what breaks. I pull it up on my screen, side by side. And I&#8217;ll be like, all right, this looks wrong, like this and this. And then you just run it again. And I wrote a prompt basically, an AI orchestration prompt that teaches the AI how to run this loop, like for a long period of time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So how I&#8217;ve built it is I&#8217;ve basically just given the AI a URL, and had multiple sessions going side by side, working on different types of URLs. And they just run, and open pull requests.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The assumption that a lot of people would make about something like this is you take the HTML site and you tell the AI how to build the block theme from it. We&#8217;re not using the AI to do that. We&#8217;re using the AI to improve on the importer. So that every time we run an import, it raises the floor just a little bit. So the more sites that you run through it and loop on it like this, the better quality overall you&#8217;re going to get for just a random, arbitrary website that you might feed it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s really just about data annotation, and taking as much as you can in finding ways to parse it without having to look at it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:41] <strong>Nathan Wrigley:</strong> Does the tool phone home. So the way you described it there was, it sounds like there was an opportunity to improve the tool for yourself on your install. But I was wondering if it phoned home so it also at the same time, improved the tool for everybody else so that the next version of the tool is better for everybody?</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I&#8217;m going to guess that it is just working locally. It&#8217;s improving your version each time. But I could be wrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:05] <strong>Chris Huber:</strong> So the prompt I share with my coworkers, and we all use it to work on the tool, so it&#8217;s more of a development thing is how I&#8217;ve built the tool is just by importing a tonne of different websites, over and over again. But the way I have it set up on GitHub is every merge to main automatically releases a new version and updates all the pins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the latest release is always the latest work that I&#8217;ve done. So, I get to benefit from the changes right away. As soon as I merge the PR, it&#8217;s in a new release and I can just keep going. It&#8217;s just not on wordpress.org yet, or anything like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:37] <strong>Nathan Wrigley:</strong> So how do we actually get hold of the tool? I&#8217;m going to link to a, a GitHub page, but just reading it into the record, it&#8217;s actually a fairly straightforward url. It&#8217;s github.com/automattic. You know the one with the two T&#8217;s, and then static-site-importer. You can go over there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How does it work? You download it. You run it locally on your machine? And then once that&#8217;s up and running, what do you see? Is there like a GUI that you have to run through? Is there a WordPress plugin component to it? Just describe the workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:07] <strong>Chris Huber:</strong> Okay. Yeah, so the Static Site importer is a WordPress plugin. And anyone can instal it on a WordPress site to turn a website into a WordPress site for sure. Using the command line locally. It works in the browser too, but there&#8217;s no UI. It&#8217;s like API based, so you&#8217;d have to call the API to do it or the CLI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Another place to use it and the easiest, probably the easiest place for anyone listening, to try it other than Riad&#8217;s website, is WordPress Studio. I added a tool to the CLI in WordPress Studio. That is, studiocreate-from. And then you can enter a URL. So it&#8217;s just one CLI command, and that orchestrates the whole thing in the background. Loads the Data Liberation agent, and then installs Static Site Importer on the site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You run it once you wait 10 or 15 minutes, and it spits out a WordPress Studio site that&#8217;s built using this tool. And that is the same way we run it on wordpress.com. Riad&#8217;s tool, the liberate.sh is a, it uses the wordpress.com API, which works the exact same way as WordPress Studio, where it loads Data Liberation Agent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And Riad&#8217;s website gives you a copy of the website that you can download and take with you, anywhere you want. A WordPress website, anywhere. You can host it anywhere. but it&#8217;s all using the same wordpress.com API on the backend. Except in WordPress Studio uses the actual tools, does that make sense?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:21] <strong>Nathan Wrigley:</strong> Thank you. That&#8217;s great. And so how successful is it? If you point it at google.com, it&#8217;s probably going to a fairly easy time with it because there&#8217;s not a lot going on. But, i&#8217;m imagining on a, let&#8217;s imagine that you went to some high-end sports website or something where they&#8217;ve got animations of people and videos, and all sorts of stuff going on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How does it hold up? For paragraphs and images and all of that kind of stuff? I&#8217;m guessing it&#8217;s pretty good. Are there any areas where you&#8217;d need to be a little bit more mindful? Because, I don&#8217;t know, just experience shows it doesn&#8217;t work out so well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:53] <strong>Chris Huber:</strong> Yeah, definitely. So if you&#8217;re watching it today, there might be some failures on things like stores. Things that have a lot of products and like really image heavy websites might have problems as well. And just like really large websites. But it gets better every single day. What I say right now might become outdated very fast on what we can and can&#8217;t handle, but it definitely is not like perfect yet, for sure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A small website, like a one page brochure website, or five pages or so. Most of the time you&#8217;ll get a pretty good copy of it. If you start to scale up to a really big, large, for example, wix.com, like the actual Wix.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:30] <strong>Nathan Wrigley:</strong> Good luck.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:31] <strong>Chris Huber:</strong> I sometimes will run that through there as a way to see how far I can get. Yeah, I&#8217;m trying to reach for the stars. So eventually I would love to be able to import this 50,000 page heavy duty, old school website, but right now it fails miserably, and it would take. The timing that was given to me last night when I was working on this was like two weeks. You&#8217;ll have a copy of wix.com, if you just let it run. And then you&#8217;d get the copy and it would just be like 10,000 pages of nonsense. We have a lot of work to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:59] <strong>Nathan Wrigley:</strong> Okay, but for a normal, typical, run of the mill, let&#8217;s go with brochure site, 12 pages, fairly ordinary stuff. Imagery, maybe a video here and there, but mostly text, CSS, maybe a tiny smattering of JavaScript sprinkled around. Forms, that kind of thing. It would do a pretty good job with that out of the box?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:17] <strong>Chris Huber:</strong> I would say like more than half the time you would get a good editable WordPress website. Not always perfect. And sometimes you would get a perfect site. But a lot of times you might have a few things that are wrong, like maybe a couple form fields, or like buttons or like menus.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One thing that happens a lot is like the header and the footer are like duplicated across every page, instead of being properly extracted into a template part. If there&#8217;s like SVG images, WordPress has a kind of a hard time handling those. So we have dealt with it. But it&#8217;s not always perfect.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the coolest things about it that I like is that blocks, so it&#8217;s static site importer is the WordPress plugin that creates the WordPress site. And then there&#8217;s a PHP package inside of it called Block Engine. Which is what handles the actual, like, mechanics of converting and creating the blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And inside of that tool I have added some like carried blocks that are in the holster ready to go, like for common elements that might appear on websites in the wild.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So like a marquee or something like that. Like a ticker that you see running across a page that Gutenberg cannot represent on its own, out of, the box. And so this tool, it knows how to build this block as if it was part of Gutenberg, so that you&#8217;ll see a real block in there. That&#8217;s my WordPress nerd favourite thing about the tool. It feels like I&#8217;m pushing on Gutenberg, finding places where Gutenberg is like maybe falling short, or just doesn&#8217;t supply the things that people need to build websites. With the right amount of attention, this might help be like, oh, we need to add some of this stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:48] <strong>Nathan Wrigley:</strong> A curious question, because we all know how AI never gives you the same thing twice. I was wondering if you fed it the same URL, do you predictably get something similar out? Or do you suffer each time a different set of, and I&#8217;m doing air quotes again, failures. So for example, you described, the SVG images, or the form fields, or the footers being duplicated or whatever it was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Is it sometimes better just to begin again, and cross your fingers and hope that the AI has a better go the second time around? Or is it always a case of go with the first version and iterate from there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:22] <strong>Chris Huber:</strong> So it works the same exact way every time. The actual process does not use any AI at all. I used the AI to build it from the outside. But the actual, It&#8217;s literally like a machine. The process doesn&#8217;t use any AI to convert the website. We have some stuff in place, like when we&#8217;re using it on wordpress.com. We&#8217;re doing migrations from non WordPress to WordPress sites, we do it for assisted migrations currently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the people running these migrations will use the tool first and see how far it gets them. And then they take Claude Code or whatever and they work on the site that came out. And they hand it over to the customer. So it gets them closer to the finish line than they would have gotten if they just had to start building the site from scratch on their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then over time we&#8217;re getting closer to the finish line, and hopefully get to the point where we can just hand people the website coming from another source and be like, here&#8217;s your exact copy of your website WordPress version. And eventually we will make that like a publicly available thing. But that&#8217;s how we&#8217;re working on it internally, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:21] <strong>Nathan Wrigley:</strong> So I think I&#8217;d misunderstood there, so the AI portion is in the creation of the tool, but the tool itself is deterministic. The tool will give predictably the exact same thing out. If you give it the URL, it&#8217;s going to parse it with a mechanised approach? It&#8217;s not relying on AI at that point. And so do it once.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then it sounded to me from the way you described it, you were holding your hands up at this point. It sounded like your had two screens open. You&#8217;ve got the output and then maybe the original. And you&#8217;re trying to iterate and just spot the errors. Okay, let&#8217;s scroll them both and see. Ah look, that&#8217;s gone a bit astray there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then presumably at this point you&#8217;re logging into WordPress. If it can be done inside the block editor, you&#8217;re doing it there. But it also sounded like you are now at .com. You are removing that part even and just doing a second run with AI at that point. Rather than logging into WordPress and using the block editor, it&#8217;s more CLI. Let&#8217;s just see if the AI can spot those mistakes, because I spotted them, prompt it and fix it in that way. That&#8217;s interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:21] <strong>Chris Huber:</strong> So I&#8217;m the one just building the tool. There&#8217;s other people working on delivering websites to customers and stuff internally. But, I started looking at the websites originally, but now I have a, I just have a prompt that I copy and paste to the AI every time and it walks through the process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And what it does is it loads both sites in a headless browser called Playwright. Basically, I have the AI look at the site as if it was the site owner. I say you&#8217;re a non-technical site owner. Open this site and look at the Gutenberg editor and see how you would feel if you came over from Wix and this was what you got.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;ll go through and click things around in the editor and be like, okay, here&#8217;s my feedback. And then I say, okay, fix everything all at once and open pull requests. And it will fan out subagents, 10 or so at a time sometimes, and open pull requests in three repos, and then I just merge them and run it again. Because the automated releases that I mentioned.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s very much trusting the machine and letting them. The machine in this case is, more able to parse this than, than a human is because it&#8217;s so much at once. And just letting them do it is what I&#8217;ve found. Describing to them what I want them to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:26] <strong>Nathan Wrigley:</strong> I&#8217;m guessing the onboarding team over on .com, presumably, if you roll the clock back a couple of years, this was all a very manual process. Find a client, get them to sign on the dotted line. Okay, they&#8217;ve got a.com account, now they want to move over. And then it would&#8217;ve been a process of, okay, let&#8217;s inspect the site, let&#8217;s get a bunch of technical people on it, and figure out what we need to migrate and when, and try to map it. Get a designer in and recreate graphics, and colour palettes, and brands and all of this kind of stuff. But it sounds like these people no longer have a, place because you just use the tool and in most cases it&#8217;s going to work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Has that in fact been the case? It sounded like over on the .com side of things, there&#8217;s like this, I don&#8217;t know, 90, 95, 99%, trust in the tool now. That must be incredible. Presumably you can onboard people much more rapidly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:14] <strong>Chris Huber:</strong> Yeah, it&#8217;s not quite that much of trust in the tool yet. It&#8217;s more one in 10 sites are getting close enough to the finish line to just be handed off. So like the original process that you mentioned is a good process for like a big site, like manual migrations and stuff. But for small sites it&#8217;s not really a good business model. It&#8217;s not economically viable to spend a lot of resources rebuilding a small website because you&#8217;re putting a lot of manual effort into one website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So what we would do mostly in the past would be, if the customer is willing to do the do it for me route, where they have our team build it for them, we would do that. But otherwise we would offer them a content import. So they can just import all their blog posts or whatever, and then rebuild the site their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This kind of gives us an option for people that were historically told no, that we can now start saying yes to them. And letting them migrate over. It&#8217;s not necessarily about reducing the labour that was going into it because it was a dead end before, and now it&#8217;s not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:10] <strong>Nathan Wrigley:</strong> And how has it been received over on the .com side of things? I&#8217;m presuming that you are in touch with these people. And even if it&#8217;s a one in 10 at the moment, we have expectations that it&#8217;ll be two in 10, and then three in 10, and by the end of next year, maybe nine in 10 or what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That gives them the opportunity to talk about other things with the clients that they&#8217;re onboarding, I suspect. Instead of just, okay, let&#8217;s figure out how to make the exact same website that we had over there, over here. That doesn&#8217;t feel like necessarily interesting work anyway.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:36] <strong>Chris Huber:</strong> Yeah, exactly. But it was always really hard to make the exact copy. And yeah, the tool has a lot of internal support and a lot of internal attention. People are rallying behind it. It&#8217;s basically what I&#8217;ve been working on full time since WordCamp US. Three months ago now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I&#8217;ve been putting full-time effort into this tool for three months now. And now it&#8217;s starting. We have a lot of momentum behind it internally now that it&#8217;s starting to get to a point where it&#8217;s actually good. It&#8217;s very cool to see this for myself. I&#8217;m very proud of the work that we&#8217;ve done. And it&#8217;s exciting. It&#8217;s just exciting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:06] <strong>Nathan Wrigley:</strong> We mentioned that there were some things that it didn&#8217;t do particularly well. Presumably it would be nice to be able to hoover up some of that in the future. What would be the roadmap items that you&#8217;ve got for the next, I don&#8217;t know, short period of time, month, two months, six months, whatever it may be. What are the bits that it can&#8217;t currently do, or the bits that there&#8217;s wrinkles in, that you could tell us about that hopefully, given the passage of time, will go away?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:30] <strong>Chris Huber:</strong> The more complicated stuff is like, installing another plugin when you&#8217;re materialising the website. So the the most obvious example is WooCommerce. If we&#8217;re detecting products in the source, we actually pre-install WooCommerce, and convert to WooCommerce blocks, and import actual products into the catalogue, and like wire up everything that we possibly can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:50] <strong>Nathan Wrigley:</strong> That&#8217;s amazing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:51] <strong>Chris Huber:</strong> It&#8217;s crazy, but it doesn&#8217;t work very well yet, because it&#8217;s very complicated. But, another thing is like is like events. Like an events calendar on a website, the tool kind of chokes on that, but it&#8217;s the same process. You install The Events Calendar plugin. You find the most widely supported and used WordPress equivalent of whatever feature you need, and you find a way to deterministically wire it up on the back end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There is a WordPress equivalent for like most things. It&#8217;s just a one at a time process to pick the one that, at least for .com. The tool itself is composable. So any developer. For forms, we use Jetpack Forms. But any developer can hook in and do whatever form provider they want, if they provide their own mappings to the tool. That&#8217;s the kind of stuff that doesn&#8217;t work quite as well right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, of course JavaScript animations and other things. WordPress has the Interactivity, API, so we do use that. More and more core blocks are coming in. Like we have the tabs now in the accordions and things like that, that we can actually represent in Gutenberg more effectively now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The real solution is just keep importing sites, you find that the tool used to choke on, it doesn&#8217;t choke on anymore, and you get further. And you just keep getting further and closer to success. The only thing it chokes on, this site is the products. Okay, so we&#8217;ll just work on improving the WooCommerce integration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah. So it&#8217;s like almost as far as you can get and then just keep. I like to think of it as raising the floor, like raising the bar is like. This is as bad as it could possibly be, and then the next time it&#8217;s a little bit better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:18] <strong>Nathan Wrigley:</strong> And it sounds like it&#8217;s going through those iterations fairly rapidly in terms of time, what three or four years ago would&#8217;ve been years into the future now increasingly feels like months, and then weeks, and then finally in a few years time, maybe days. A lot of this stuff will be taken on in short measure, things like an events system, or a WooCommerce system or an LMS kind of system. Maybe that stuff will be in scope in the near future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The project, obviously being on GitHub, and being a WordPressy thing is open source and I&#8217;m, just curious whether or not you are doing this hand in hand with any other people? Or is it just a project within Automattic? Or are you getting kind of intuitions from WordPress agencies out there who are obviously having to do this kind of work?</p>\n\n\n\n<p class=\"wp-block-paragraph\">They&#8217;re bringing in clients from all over the place and trying to convert them over to WordPress. I just wondered if there was any collaboration going on, or do you wish there to be collaboration?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:12] <strong>Chris Huber:</strong> I think something like this should be part of WordPress Core. I don&#8217;t know that necessarily this exact tool or this approach. There&#8217;s a lot of work in the ecosystem around this area, like Human Made has a tool like this. And then Pascal from WordPress Core, is working on this in Gutenberg, not the exact same thing, but some way to convert HTML to blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I just think it&#8217;s a big challenge for the WordPress ecosystem that if it gets solved can help move the whole project forward and help make us more future proof. Just because AI is so good at generating HTML, and that&#8217;s what kind of becoming the native format of the internet now. Maybe always has been, but just making that translatable into WordPress is something important I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:53] <strong>Nathan Wrigley:</strong> Yeah, I think so. And obviously in an era where market share in the WordPress space is no longer seemingly guaranteed to just keep climbing. People face with that decision of, okay, I&#8217;ve got a website, it&#8217;s now starting to look a bit stale, but rather than throw the baby out with a bath water, we&#8217;ll, okay, we want an alternative CMS. We want to upgrade, see where we can go. It feels like a tool like this makes WordPress a bit of a forerunner, actually.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re going to pick a CMS, have a CMS where there&#8217;s a pretty good chance that by clicking a button you can bring most of your existing stuff across. I don&#8217;t know what the other CMSs do in that regard. Maybe they do nothing, but this does feel like a tool in WordPress&#8217;s arsenal, which is pretty compelling. I would hope that it would bring a lot of people in our direction.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:42] <strong>Chris Huber:</strong> I hope so too, and I agree. I think the fact that it can exist. It takes one of the points of WordPress that has been difficult for people to embrace, which is the block editor. And it almost turns it into an advantage. Because then you get a WYSIWYG version of every website. Whereas if you were to generate a static site with AI and go and host it on a static host, you don&#8217;t have the CMS. If you want to add another blog post, you have to generate the page, upload it to the site. And of course there are solutions to this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What if you just want to change one word? You just want to go into the block editor and change the one word. Then you can do that and like without having to build the whole page from scratch in the editor. You have to be good at it and know what you&#8217;re doing to build a custom website using the block editor, I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:26] <strong>Nathan Wrigley:</strong> This is going to be a discussion which will go on, I think in the days, weeks, and months to come. Obviously everybody at the minute is very beguiled by the interface of building a website through some kind of chat mechanism. It&#8217;s so fascinating that&#8217;s possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then the reality of maintaining that, and understanding how that page even got there. And where do the assets, on that page even live? And how do I modify the title of the hero section over here? All of that has yet to land with ordinary people. Again, doing air quotes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:04] <strong>Chris Huber:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:05] <strong>Nathan Wrigley:</strong> If you&#8217;re very technical, you can probably figure all that stuff out, because you were probably the person that created that AI based site anyway. But if you&#8217;re not technical and your job is just to occasionally modify content, or inspect somebody else&#8217;s content, and click publish when it met the guidelines that you&#8217;d got as an organisation. You&#8217;re not going to care about some sort of CLI interface or getting an AI to do that for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You just want to be in, out, and then move on, because WordPress is not what makes up the majority of your day. I think all of that stuff is going to hit us in 2027, and it&#8217;ll be interesting to see where we land and where the landscape moves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:41] <strong>Chris Huber:</strong> Yeah, I hope that we can continue to grow WordPress definitely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:45] <strong>Nathan Wrigley:</strong> Okay, that&#8217;s really interesting. I&#8217;ll read into the record one more time the tool itself. So github.com/auttomatic, two ts, /static-site-importer. You can go over there and make comments. It&#8217;s a GitHub page so you can do all of that normal stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If people wanted to find you, Chris, do you hang out online anywhere? If people wanted to contact you and had intuitions on where this should perhaps go in the future?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:11] <strong>Chris Huber:</strong> Yeah, they can reach out to me on x x.com/chubes4, C-H-U-B-E-S four. They can also find my GitHub, which is the same tag. I have my personal WordPress site at extrachill.com, is like my main site. Then I have my other one, chubes.net. Or, just leave a pull request or a GitHub issue, me or my AI agent will reply.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:33] <strong>Nathan Wrigley:</strong> This is how it is in the year 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:35] <strong>Chris Huber:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:37] <strong>Nathan Wrigley:</strong> Okay Chris, absolutely fascinating. Let&#8217;s hope that the tool manages to do a lot more than you&#8217;ve described. It sounds like you&#8217;ve got a very extensive, and interesting, roadmap going on, but thank you for bringing that to us and, thank for explaining it all to us today. Appreciate it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:49] <strong>Chris Huber:</strong> Yeah. Thanks for your time. Thanks for having me.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://profiles.wordpress.org/extrachill/\">Chris Huber</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris’s journey with WordPress began back in his college days, first as a writer and blogger and eventually progressing to software engineering. After moving his personal site, extrachill.com, to WordPress in 2018, Chris went deeply into WordPress, developing custom plugins and exploring all the corners of the platform. His passion for experimentation and creative tech led him to Automattic, where he now helps shape the WordPress experience as a software engineer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our discussion centers around two main topics: Data Liberation and the Static Site Importer tool. We focused upon the evolving landscape of website migration and ownership. Chris explains how Data Liberation aims to make it easier for users to take control of their site, whether they&#8217;re moving to WordPress from platforms like Wix, Squarespace, or Drupal, or just want portability for their data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into the Static Site Importer, which takes this a step further by converting any static HTML / CSS website into a fully editable WordPress block theme, headers, footers, and all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris walks us through how these tools work in tandem, highlighting the mechanics behind website crawling, mapping HTML elements to Gutenberg blocks, and handling complex features like WooCommerce and calendars.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the continuous improvement of these tools, how each migration helps raise the bar for future imports, and how this project could fundamentally change the way people move websites between platforms.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re curious about the future of website migration and how WordPress is removing the hurdles for users who want to truly own and manage their content, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Chris&#8217; <a href=\"https://extrachill.com\">extrachill.com</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\">Chris&#8217; <a href=\"https://chubes.net\">chubes.net</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/automattic/static-site-importer\">Static Site Importer</a> on GitHub</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.wordpress.com/studio/\">WordPress Studio</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/data-liberation/\">Data Liberation Project</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://liberate.sh\">liberate.sh</a> website</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://x.com/chubes4\">Chris on X</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:37;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Switching off PHP until upgraded\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593199\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2026/10/21/switching-off-php-until-upgraded/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:635:\"<p class=\"wp-block-paragraph\">There&#8217;s going to be an <a href=\"https://www.php.net/archive/2026.php#2026-10-20-1\">emergency PHP release</a> made in just over 2 hours. It&#8217;s to address a critical security bug. </p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m not sure how long it&#8217;ll be before Ubuntu updates, but I will preload a bunch of posts here and on inphotos.org using WP Super Cache and turn off PHP until it&#8217;s updated. The files will be served by Apache&#8217;s mod_rewrite, so no PHP involved at all. Uncached pages won&#8217;t be so lucky, but at least some pages will still be live.</p>\n\n#PHP #WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 11:46:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:38;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"WordPress.org blog: WordPress 7.2 Beta 1 is Ready for Download and Testing\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21813\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:17084:\"<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.2 Beta 1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.2 Beta 1 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-beta1.zip\">Beta 1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-beta1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.2 Beta 1 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Editing Experience</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Responsive Design Controls</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Building on the responsive design improvements introduced in WordPress 7.1, WordPress 7.2 expands viewport-specific styling to additional design tools and blocks. Creators gain more granular control over how layouts and visual settings adapt across screen sizes, including responsive Gallery settings for columns, image cropping, and aspect ratios.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/80388\">GitHub #80388</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82003\">#82003</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Improved Global Styles and Design Tools</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21825\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 makes site-wide styling easier to manage with a new <em>Customized</em> filter for finding blocks with modified styles and inherited Global Styles values displayed directly in block inspector controls. Expanded design tools and support for styling form elements provide additional flexibility when creating a consistent visual identity across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/82520\">GitHub #82520</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/76525\">#76525</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/34198\">#34198</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84657\">#84657</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Text Shadow Support</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces new text shadow controls, giving creators more ways to add depth and emphasis to their content. Text shadows can be customized through block settings and defined as presets in <code>theme.json</code>, making it easier to maintain consistent typography across a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">GitHub #73320</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79584\">GitHub #79584</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">Trac #65869</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Easier Navigation Management</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Improvements to the Site Editor make managing navigation links more intuitive. Creators can add, organize, and edit navigation items directly from the editor sidebar, making it easier to maintain site menus without interrupting their editing workflow.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/77069\">GitHub #77069</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Better Collaboration with Notes</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21820\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces Emoji reactions on notes and a new toolbar icon that makes Notes easier to access and manage. Notes move to the editor canvas, bringing conversations directly into the margin. Users can now keep Notes and the block settings sidebar open simultaneously, making it easier to review feedback while editing content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A new minimized Notes mode reduces visual clutter, while improvements to positioning and display create a smoother, more consistent collaboration experience.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/79970\">GitHub #79970</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83786\">GitHub #83786</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/80015\">GitHub #80015</a>, <a href=\"https://core.trac.wordpress.org/ticket/64638\">Trac #64638</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster, More Efficient Media Uploads</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands client-side media processing to the Media Library, allowing images to be resized, compressed, and converted directly in the browser before being uploaded. This can improve upload performance, reduce server resource usage, and provide better support for modern image formats, particularly on hosting environments with limited image-processing capabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65661\">Trac #65661</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/12585\">GitHub #12585</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">New “On This Day” Dashboard Widget</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a new <strong>On This Day</strong> dashboard widget that helps users rediscover content published on the same date in previous years. By highlighting posts from the site&#8217;s history, the widget makes it easier to revisit past content, celebrate milestones, and find opportunities to refresh or reshare older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65116\">Trac #65116</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Block Editor Usability Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 includes a collection of smaller improvements aimed at reducing friction in everyday editing. These changes include clearer error messages, more helpful feedback when something goes wrong, and refinements to common editor interactions, making the editing experience more predictable and approachable.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21821\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/81453\">GitHub #81453</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82496\">#82496</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84656\">#84656</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84649\">#84649</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">A More Consistent WordPress Admin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 continues modernizing the administration experience by replacing legacy Dashicons in the admin bar and sidebar with icons from the WordPress icon library. The updated icons bring greater visual consistency between the traditional WordPress dashboard and newer editing interfaces.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/wordpress-develop/pull/12270\">GitHub #12270</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">An Updated Block Settings Experience</h3>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21822\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A new DataForm-powered inspector introduces a refreshed approach to managing block settings in the editor. Built on the DataForm component system, this work aims to provide more consistent controls and a more extensible foundation for future block editing improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg\">GitHub Gutenberg</a> · <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\">Call for Testing</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Faster WordPress Administration</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 improves admin performance by modernizing how scripts and stylesheets are loaded. Instead of combining assets into large files, WordPress now loads them individually for better browser caching. A new prefetching mechanism also anticipates which admin screen users are likely to visit next, loading its resources in advance to make navigation between the dashboard, post lists, and editor faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/57548\">Trac #57548</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">For Developers</h2>\n\n\n\n<h3 class=\"wp-block-heading\">New Secrets API</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 introduces a <strong>Secrets API</strong>, providing developers with a standardized, secure way to store sensitive credentials such as API keys and authentication tokens. The API supports encryption at rest, credential rotation, and customizable storage providers, helping plugins and integrations manage sensitive information more securely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://core.trac.wordpress.org/ticket/66187\">Learn more (Trac #66187)</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Random Content Redirects</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 adds support for random content redirects, allowing visitors to discover a randomly selected post through a dedicated URL. This provides a simple way to encourage content exploration and help readers rediscover older posts.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/64498\">Trac #64498</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">More Powerful APIs for Developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 expands the <strong>Abilities API</strong> with new capabilities for accessing and querying WordPress data, providing a more consistent foundation for integrations, automation, and AI-powered tools. (<a href=\"https://core.trac.wordpress.org/ticket/66268\">Trac #66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/64605\">#64605</a>, <a href=\"https://core.trac.wordpress.org/ticket/64657\">#64657</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Enhancements to the <strong>Interactivity API</strong> introduce new ways to render trusted HTML and manage reactive navigation, giving developers more flexibility when building dynamic, interactive blocks. (<a href=\"https://core.trac.wordpress.org/ticket/66246\">Trac #66246</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83092\">Gutenberg PR #83092</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional improvements to the <strong>HTML API</strong>, block supports, and responsive design tools provide more reliable markup processing and greater control over how custom blocks are styled and displayed across devices. (<a href=\"https://core.trac.wordpress.org/ticket/65824\">Trac #65824</a>, <a href=\"https://core.trac.wordpress.org/ticket/66150\">#66150</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a>)</p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Details on what to test in WordPress 7.2 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the<a href=\"https://make.wordpress.org/test/\"> testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 will include new features that were previously only available in the Gutenberg plugin. Learn more about Gutenberg updates since WordPress 7.1 in the <a href=\"https://make.wordpress.org/core/tag/gutenberg-new/\">What’s New in Gutenberg</a> posts for versions <a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">23.7</a>, <a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">23.8</a>, <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">23.9</a>, <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\">24.0</a>, <a href=\"https://make.wordpress.org/core/2026/09/30/whats-new-in-gutenberg-24-1-30-september/\">24.1</a>, <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\">24.2</a>, and 24.3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s new in WordPress 7.2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">With so much in progress for WordPress 7.2 Beta 1, this is still only the beginning; expect continued refinement with each Beta and RC release ahead of the final release on <strong>December 8, 2026</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Just for you: a Beta 1 haiku:</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Ipsum takes the stage<br />Secrets bloom, designs take shape<br />New blocks come alive</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/adamsilverstein/\"><span class=\"mentions-prefix\">@</span>adamsilverstein</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/westonruter/\"><span class=\"mentions-prefix\">@</span>westonruter</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/markoserb/\"><span class=\"mentions-prefix\">@</span>markoserb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/im3dabasia1/\"><span class=\"mentions-prefix\">@</span>im3dabasia1</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/jorbin/\"><span class=\"mentions-prefix\">@</span>jorbin</a>, and <a class=\"mention\" href=\"https://profiles.wordpress.org/noruzzaman/\"><span class=\"mentions-prefix\">@</span>noruzzaman</a><em> for proofreading and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 16:02:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:39;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Open Channels FM: Community Without the Noise, Revisited\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564390\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"https://openchannels.fm/community-without-the-noise-revisited/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"A commentary on building meaningful online communities that prioritize value and listening over constant activity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:46:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:40;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"OpenStation Blog: OpenStation: turn wp-admin into a desktop, and try it in 30 seconds\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1495\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:102:\"https://openstation.blog/2026/10/20/openstation-turn-wp-admin-into-a-desktop-and-try-it-in-30-seconds/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2722:\"<p class=\"wp-block-paragraph\">OpenStation is a free WordPress plugin that turns wp-admin into a desktop. Every admin screen opens in its own window that you can move, resize and keep open next to the others. You can try it in your browser right now, with nothing to install.</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Can&#8217;t see the video? <a href=\"https://www.youtube.com/watch?v=g5MLB3WMlCc\">Watch it on YouTube</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why we built it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Most of us spend the day jumping between screens in wp-admin. You open a post, go back to the list, check the media library, then go back again. With OpenStation, those screens stay open side by side, so you don&#8217;t lose your place.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What you get</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A window for every admin page: posts, media, settings, plugins</li>\n\n\n\n<li>A dock with your whole admin menu, including your other plugins</li>\n\n\n\n<li>Several desktops, for example one for writing and one for site settings</li>\n\n\n\n<li>Wallpapers, widgets and accent colors</li>\n\n\n\n<li>Cmd+K to jump anywhere fast</li>\n\n\n\n<li>Your windows are still open when you come back</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Try it in your browser</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Go to the <a href=\"https://wordpress.org/plugins/desktop-mode/\">OpenStation page on WordPress.org</a> and click <strong>Live Preview</strong>. It runs a full WordPress site with OpenStation in your browser tab, so you can&#8217;t break anything.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Install it on your site</h2>\n\n\n\n<ol class=\"wp-block-list\">\n<li>In your admin, go to Plugins → Add New and search for &#8220;OpenStation&#8221;</li>\n\n\n\n<li>Click Install Now, then Activate</li>\n\n\n\n<li>Click the desktop icon in the top-right corner of the admin bar</li>\n</ol>\n\n\n\n<h2 class=\"wp-block-heading\">It&#8217;s safe to try</h2>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation is opt-in for each user, so the rest of your team keeps the normal admin. Click the same icon to go back to the classic view. If you deactivate the plugin, wp-admin goes back to exactly how it was. It doesn&#8217;t change WordPress core.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Tell us what you think</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Have a question? Ask in the <a href=\"https://wordpress.org/support/plugin/desktop-mode/\">support forum</a>. Found a bug or have an idea? <a href=\"https://github.com/WordPress/openstation/issues\">Open an issue on GitHub</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 13:44:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:41;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Open Channels FM: More Code, More Problems? What AI-Generated Software Means for Us\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563871\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://openchannels.fm/more-code-more-problems-what-ai-generated-software-means-for-us/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:327:\"AI tools have simplified app creation, enabling rapid prototyping. However, the challenge now lies in discerning which ideas are genuinely valuable to users. As anyone can create apps quickly, the focus should shift from mere production to understanding user needs and ensuring the apps solve real problems to avoid mediocrity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 10:01:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:42;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:41:\"Donncha: Travel Steps is a travel journal\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593168\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://odd.blog/2026/10/19/travel-steps-is-a-travel-journal/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10115:\"<p class=\"wp-block-paragraph\">I made a WordPress plugin for my holidays. It&#8217;s called <a href=\"https://wordpress.org/plugins/travel-steps-storyteller/\">Travel Steps Storyteller</a>, and it turns a trip into a page with a map down one side and the story of each day down the other.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593171 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/01-trip-header.avif\" width=\"2000\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Every photo I take ends up in <a href=\"https://immich.app\">Immich</a>, on my own server. My phone sends where I&#8217;ve been to <a href=\"https://dawarich.app\">Dawarich</a>, on the same server. So after a trip I have all the photos and the whole route, sitting in two apps on my private server. The travel apps that make nice trip pages want your photos and your location on their servers. I&#8217;d rather keep them on mine.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How it works</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You make a trip, give it a first and last day, and press Sync. Travel Steps asks Dawarich for your location over those days, and Immich for the photos you took. You can pick one Immich album instead. If you don&#8217;t use Immich at all, upload the photos to the trip. It will detect the start and end dates from the uploaded photos, or an Immich album too.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593182 not-transparent\" height=\"1480\" src=\"https://odd.blog/files/2026/10/08-sync-and-steps.avif\" width=\"1520\" /><figcaption class=\"wp-element-caption\">One sync, and a step for each day.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Sync makes a draft post for every day that has favourite photos. Each one is a &#8220;step&#8221;. It splits the day into places too. A new place starts when a favourite is more than 2 km from the last one and in a different town. Each place gets a heading and a block of photos, so all that&#8217;s left is the writing.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593175 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/09-block-editor.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">Each day is a post you write in the block editor. The photos under each heading come straight from Immich.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Place names come from <a href=\"https://www.geonames.org\">GeoNames</a> data that ships with the plugin, so naming a town doesn&#8217;t send your location anywhere. Immich only names a place from a photo&#8217;s own GPS. A photo from a camera without GPS gets placed from your Dawarich history instead, and named the same way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Publish the days you want people to see. Drafts stay private, and so do their photos.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593174 not-transparent\" height=\"1250\" src=\"https://odd.blog/files/2026/10/02-map-timeline.avif\" width=\"2000\" /><figcaption class=\"wp-element-caption\">The map follows you as you scroll. Get to day 3 and day 3&#8217;s markers light up.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The distance at the top follows the whole route, flights included. GPS glitches that put you in the Atlantic for a second are dropped. Anything you&#8217;d have needed to travel faster than 1,080 km/h to reach counts as a glitch. Sorry, Concorde.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Your photos stay at home</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Visitors never talk to Immich. WordPress fetches each photo, caches it and serves it itself, so Immich and the original files stay private. It caches a trip&#8217;s photos in the background after a sync. The trip keeps working when Immich is down. A daily sweep deletes cached photos older than a number of days you choose, whether a trip still uses them or not, and they&#8217;re fetched again the next time someone looks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Photos you upload to a trip keep their GPS in the original, but it&#8217;s stripped from every copy WordPress makes, and only those copies are ever sent. A trip can have a password, and you can let some logged-in people skip it.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Pin, hide, cover</h2>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full\"><img alt=\"\" class=\"wp-image-89593176 not-transparent\" height=\"1060\" src=\"https://odd.blog/files/2026/10/03-photo-tools.avif\" width=\"1300\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Hover over a photo to pin it (always show it), hide it, or make it the trip&#8217;s cover. The rest of the day&#8217;s photos sit behind a &#8220;Show more photos&#8221; link.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On phones, those buttons show up after you press Edit photos as illustrated by the images below.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593177 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/04-phone-trip.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593178 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/05-phone-edit-photos.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Tap a photo and it opens full screen. On a phone you swipe from one photo to the next, edge to edge. On a desktop there are arrows, and the arrow keys work too.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593185 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/07-phone-lightbox.avif\" width=\"924\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-89593179 not-transparent\" height=\"2000\" src=\"https://odd.blog/files/2026/10/06-phone-lightbox-swipe.avif\" width=\"924\" /></figure>\n</div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Try it</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Here&#8217;s a <a href=\"https://playground.wordpress.net/?blueprint-url=https://raw.githubusercontent.com/donnchawp/travel-steps/master/demo/blueprint.json\">demo in WordPress Playground</a>. It&#8217;s a week in the west of Ireland, running in your browser that installs nothing. Stand-in Immich and Dawarich servers feed the real sync code with photos from Unsplash. You&#8217;re logged in as an admin, so press Sync, pin and hide photos, and edit the days in the block editor. It all disappears when you close the tab.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The code is <a href=\"https://github.com/donnchawp/travel-steps\">on GitHub</a> and you can install it from the WordPress plugin repo <a href=\"https://wordpress.org/plugins/travel-steps-storyteller/\">here</a>. To install it, look for &#8220;Travel Steps Storyteller&#8221; in the plugins page. It needs WordPress 6.7 and PHP 8.0. Immich and Dawarich are both optional. It has been submitted to WordPress.org but if you read this blog, you&#8217;ll know how to install a plugin from a zip file!</p>\n\n\n\n<h2 class=\"wp-block-heading\">WpApp</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Travel Steps is built on <a href=\"https://github.com/akirk/wp-app\">WpApp</a>, Alex Kirk&#8217;s framework for building apps on top of WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A plugin usually adds screens to wp-admin, or puts its pages inside your theme and hopes the CSS gets along. A WpApp app gets its own URLs instead (<code>/travel-steps/</code> here), and its pages are plain HTML with no theme in the way. WordPress still does the boring work: users and logins, roles, the block editor, the REST API, cron and the database. WpApp adds the bits in between:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>URL routing, using WordPress rewrite rules,</li>\n\n\n\n<li>pages that don&#8217;t load your theme,</li>\n\n\n\n<li>the admin bar on every page, with the app&#8217;s own icon (the green map at the top of my screenshots),</li>\n\n\n\n<li>access control using WordPress capabilities.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You can start one with <code>composer create-project akirk/create-wp-app my-app</code>. Alex has a <a href=\"https://wpapps.kirk.at/\">showcase of apps built with it</a>, including a cookbook and a family wiki.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Built with Claude Code</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I wrote Travel Steps with <a href=\"https://claude.ai/code\">Claude Code</a>. The first commit was on 11 October, and there are many more now. Most of the work went round the same loop. I file an issue, Claude fixes it test-first on a branch and opens a pull request, and other agents review it. I deploy it to my own server and try it. The tests run in WordPress Playground too, the same as the demo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you run Immich, give it a whirl. Bug reports welcome on GitHub <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"has-small-font-size wp-block-paragraph\">Demo photos from <a href=\"https://unsplash.com\">Unsplash</a>: Cliffs of Moher by <a href=\"https://unsplash.com/photos/Zf9bvJ6182k\">Jarek Skowron</a>, Temple Bar by <a href=\"https://unsplash.com/photos/-ABmxr3Yo4Y\">Sarah</a>, Galway by Daniel Zbroja and Anna Hunko, Kilronan by Jonathan Borba. Map © <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors.</p>\n\n#TravelSteps #WordPress #WordPressplugin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 14:15:48 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:43;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"WordCamp Central: WordPress Campus Connect Ahmad Education, Dhaka 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16498954\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"https://central.wordcamp.org/news/2026/10/wordpress-campus-connect-ahmad-education-dhaka-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4344:\"<div class=\"wp-block-columns has-black-background-color has-text-color has-background has-link-color has-small-font-size wp-elements-20 is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\" style=\"color: #ffffff;\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<h3 class=\"wp-block-heading has-white-color has-text-color has-link-color wp-elements-21\">The Truly Meaning moment in this event</h3>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-22 wp-block-paragraph\">Campus Connect Event Successfully Completed!</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-23 wp-block-paragraph\">We are pleased to share that the Campus Connect<strong> </strong>event, held on Thursday, October 1st, was successfully completed with the participation of students from Ahmad’s Education.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-24 wp-block-paragraph\">Ahmad’s Education has already collaborated with WordPress and successfully completed two batches. This event was another valuable opportunity to strengthen our collaboration, share knowledge, and inspire students to explore new learning opportunities.</p>\n\n\n\n<p class=\"has-white-color has-text-color has-link-color wp-elements-25 wp-block-paragraph\">A heartfelt thanks to the WordPress team, the organizers, and all the students who contributed to making this event successful.<br />Looking forward to more collaborations and learning opportunities together!</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large is-style-default wp-duotone-unset-2\"><a href=\"https://central.wordcamp.org/files/2026/10/group2-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499417\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/group2-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-scaled.jpg\"><img alt=\"\" class=\"wp-image-16499418\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/10/ahmadsEducation-1024x768.jpg\" width=\"1024\" /></a></figure>\n</div>\n</div>\n\n\n\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<div class=\"wp-block-columns are-vertically-aligned-center is-layout-flex wp-container-core-columns-is-layout-8f761849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center has-white-background-color has-background is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\"><img alt=\"\" class=\"wp-image-16499419\" src=\"https://central.wordcamp.org/files/2026/10/abdullah-noman.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\"><img alt=\"\" class=\"wp-image-16499420\" src=\"https://central.wordcamp.org/files/2026/10/aminul.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\"><img alt=\"\" class=\"wp-image-16499424\" height=\"1536\" src=\"https://central.wordcamp.org/files/2026/10/atikur-rahman-geting-certificate.jpg\" width=\"2048\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\"><img alt=\"\" class=\"wp-image-16499423\" src=\"https://central.wordcamp.org/files/2026/10/guies-3.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\"><img alt=\"\" class=\"wp-image-16499421\" src=\"https://central.wordcamp.org/files/2026/10/guist-1.jpg\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large is-style-default\"><a href=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\"><img alt=\"\" class=\"wp-image-16499422\" src=\"https://central.wordcamp.org/files/2026/10/guist-2.jpg\" /></a></figure>\n</figure>\n</div>\n</div>\n</div></div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 11:04:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"ATIKUR RAHMAN\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:44;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Why Fast AI Inference Is a Game Changer for Developers\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563865\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://openchannels.fm/why-fast-ai-inference-is-a-game-changer-for-developers/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:332:\"In tech, speed can make all the difference. One topic that doesn&#8217;t get enough attention is just how much faster AI inference is changing the way developers work. Training AI models still grabs the headlines with all the talk about big clusters and huge data sets, but the real impact for most developers happens when [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 09:48:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:45;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"Dennis Snell: Radical explorations in agentic development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://fluffyandflakey.blog/?p=4166\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"https://fluffyandflakey.blog/2026/10/19/radical-explorations/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:57796:\"<p class=\"wp-block-paragraph\">In mid-April 2026 my employer started a project called “Radical Speed Month” to step away from our existing structures and processes, make space for people to dive more deeply into AI tooling, and try to build new or sleeping ideas. My participation in this experiment ran until late September and I stacked up a lot of explorations without having written about them or about the process. In this post I’d like to highlight some of the results of this time and share some learnings.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Selected lessons</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Massive agentic deployment demands heavy storage and generic compute capacity — inference is not the only bottleneck. This is necessary to support massively parallel checkouts of code, benchmarking, analysis of other software and data, running hierarchies of thousands of test workers and headless browsers, generating and analyzing image and video artifacts, creating indexes, and more.</li>\n\n\n\n<li>Instructing an agent to “find the five hidden defects” is more effective at finding real issues than asking if there are any hidden defects. They may return false claims, but they try to answer the questions they are prompted — it’s not that different than the comparison between asking someone what in their day brought them a smile, or what was difficult for them, rather than asking “how was your day?”</li>\n\n\n\n<li>Agents with web searching capabilities are powerful knowledge-retrieval and aggregation tools. Reports they generate to aid in developing code can be more effective than asking the agents to generate the code directly.</li>\n\n\n\n<li>Models today are incredibly powerful, but guiding human insight is also powerful. Autonomous agentic activity demonstrated a tendency to produce more evidence of accomplished work than actual accomplished work. In a strange way this might reflect the training dataset: corporations must also guard against the dangers of overly-burdensome paperwork.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Projects</h2>\n\n\n\n<p class=\"wp-block-paragraph\">All of the projects here were almost entirely built by AI agents, but with my guidance and supervision. Therefore, credit for each of them does not rest entirely with me. However, for the sake of brevity I will omit mentioning in each one that AI tooling was the actual producer.</p>\n\n\n\n<span id=\"more-4166\"></span>\n\n\n\n<p class=\"wp-block-paragraph\">Each project below is assigned a truly unscientific evaluation:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> The project succeeded with clear value.</li>\n\n\n\n<li><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> The project completed its goals, but the value is unclear.</li>\n\n\n\n<li><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> The hard work has completed, but I need to close the loop and deploy it.</li>\n\n\n\n<li><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> The idea is sound but not ready; it needs more development.</li>\n\n\n\n<li><img alt=\"❌\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/274c.png\" style=\"height: 1em;\" /> The project failed to bear fruit for any reason.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">My personal favorites:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#fix-a-driver-bug\">Fix bugs in proprietary hardware drivers</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#gather-empirical-data\">Gather empirical evidence to guide development decisions</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#crawl-it-all\">Stream real-world HTML from Common Crawl</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#php-gameshark\">Provide deep insight into PHP script execution</a></li>\n\n\n\n<li><a href=\"https://fluffyandflakey.blog/tag/wordpress/feed/#wp-de-rtc\">Rapidly prototype a comprehensive collaborative editing environment for WordPress</a></li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Tools</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Because I expected a short availability for the enhanced AI access, I prioritized building, early on, tools whose value would outlast the project. Generally I prefer working in offline or local environments, so I built archivers for several services which are only available when connected to the Internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While MCP servers were very popular at this time, I have always been unhappy with the load centralization and amplification they create. The same is true for any online resource against which agents perform searches. My intuition is that it’s more considerate to those services to make one batched update, to download all new data since the last sync, than it is to make repeated queries which might overwhelm their servers and fetch the same resources over and over.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Being offline and local, the archivers are extremely fast and operate in the terminal where I prefer to interact.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> GitHub archive</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Finding GitHub’s search functionality lacking, and wishing for a chronological stream of my activity, I built <code>github-archiver</code> so I could have the tools and performance I wanted. This initially supported searching through PRs, issues, and comments, as well as rendering my own activity in a reverse-chronological view. I eventually added two additional views for replies: people I replied to, and people who had replied to me. This gives me great awareness of my recent conversations and has helped me to avoid losing conversations. Sometimes I struggle to find a PR that I meant to follow-up on, but it disappears from my GitHub notifications and I can’t remember the exact wording that will turn it up in a search result. I even tend to forget in which code repository it was left, so my tool aggregates activity across all archived repositories.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The basic design is a compressed HTTP cache of the GitHub API. When fetching or updating, it respects rate limits and leans on HTTP headers to avoid wasted transfers. After some work with banking APIs several years ago, I found that storing raw HTTP responses proved more flexible than parsing into a custom internal data type, as it lets me rewrite logic in the app later without having to re-download the entire archive. This came in handy several times as I expanded the search index and added more functionality.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The tool renders GitHub content as richly-formatted and highlighted text in a console unless running outside of an interactive TTY. It renders Markdown and HTML content into this rich text format and lays out meta elements in a meaningful way. Its speed, zero-network dependence, and minimized output make it a good fit for agents that would otherwise be hammering GitHub’s API, waiting, and wasting tokens on irrelevant content.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter\"><img alt=\"github-archiver renders PRs, Issues, comments, and line-level comments into the terminal with parsed markup, syntax highlighting, code snippets, and links created via ANSI terminal codes. It provides an alternative to the slower browser-based interface.\" class=\"wp-image-4214\" height=\"409\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.11.29-PM.png?resize=740%2C409&#038;ssl=1\" width=\"740\" /></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Trac archive</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Just like the <code>github-archiver</code>, I built a <code>trac-archive</code> for <a href=\"https://core.trac.wordpress.org\">WordPress’ Trac</a> system. It is feature-similar to the GitHub archiver, but provides an additional perk: because bots relay messages from GitHub back into Trac, issues often have two markup formats in use simultaneously. My <code>trac-archive</code> first parses its content according to Trac’s own system, but then it additionally parses Markdown where it finds it. It shares much of the rendering logic with the <code>github-archiver</code> and provides a clearer experience than the web view due to the additional parsing, syntax highlighting, and ability to exclude bot traffic from the results.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.49.04-PM.png?ssl=1\"><img alt=\"Like the github-archiver, the trac-archive renders tickets into the terminal with parsed markup, syntax highlighting, code snippets, and links created via ANSI terminal codes. It provides an alternative to the slower browser-based interface and in many ways a more usable one due to the way Trac aggregates content from GitHub.\" class=\"wp-image-4228\" height=\"459\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-3.49.04-PM.png?resize=740%2C459&#038;ssl=1\" width=\"740\" /></a></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Review the evolution of a series of commits over time</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><code>git-sequence-patch</code> was used to help me understand the full scope of the WordPress collaborative editor project. Since many large features or projects span many commits and possibly even months or years of work, this tool reads a number of <code>git</code> commit SHAs and will build a fictitious patch that more or less represents how the entire project would be proposed were it to be proposed against the latest branch head. Another way to look at this is to generate one massive revert commit for the original feature and all descendant changes to it since its inception.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is a project I had been wanting to build for a long time; for each of the given commits, it tracks which lines were changed by the commits, and then steps forward through the branch history, noting when other commits also modify or remove those lines. Once it completes at the branch head, it prepares a patch to replace all of those lines with the code that was there before the original patch, and reverse the patch. This means that it doesn’t produce a patch that would actually merge, but it produces a patch that’s useful for understanding the full scope of how a change evolves over time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It’s line-oriented and so would miss some obvious scope. For example, if tracing the sequence for a new function, it will miss a later change which calls into that function. This would actually be possible to add to the tool as an enhancement, but it wasn’t necessary for my purposes at the time and I think it would remain ideally an option rather than a default behavior.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I spend a lot of time trying to quickly understand entire systems that I didn’t write or have any experience with, and this tool is a delight for answering the question: “how has this change evolved through time?”</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"crawl-it-all\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Analyze real-world HTML from Common Crawl</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To better test the HTML API against real HTML documents, I built <code>cc-analyzer</code>, which feeds data from the Common Crawl index into a user-supplied PHP script. This operates in two modes: streaming and batched. In streaming mode it continuously sends HTML documents from the archive into the analysis script. In batched mode, it saves documents from the archive into a subdirectory and then may be invoked again to re-run those documents through specific analysis scripts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This project has greatly benefited the testing and verification of the HTML API, and informed decisions about what actual HTML syntax patterns exist on the web and what concerns are practical and which are esoteric. Throughout this grand experiment I have examined hundreds of thousands of HTML documents to test the HTML API code, to understand reported and actual text encodings of websites at large, to benchmark changes and optimizations for the HTML API, and to understand parsing needs of real HTML documents.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Instantly search code from the WordPress ecosystem</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://veloria.dev\">Veloria.dev</a> (formerly WPDirectory.net) provides fast code search across all of the plugins and themes listed on the WordPress directory. It was experiencing elevated outage rates and I decided at the start of September to recreate it locally as a single binary with a simple compressed offline archive. Previous efforts to <a href=\"https://github.com/markjaquith/WordPress-Plugin-Directory-Slurper\">slurp the directory</a> left efficiency gains on the table and output around 120 GB of data on the filesystem. By taking advantage of available concurrency, streaming computation as resources are downloaded, pruning the stored files to those which were being indexed, and saving into a custom compressed binary object, my <code>wp-code-search</code> tool was able to archive the directory in five hours storing only 5 GB among three data files: a compressed archive of the source files, a search index, and a metadata archive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This idea originally came from Dan Luu, who <a href=\"https://danluu.com/perf-opt/#build-an-index\">commented</a> that “<em>if we&#8217;re repeatedly searching for text on a computer, the obvious thing to do to speed that up isn&#8217;t to write a native code compiler for regex matching, it&#8217;s to create an index</em>.” Code searches across the entire directory typically return within 10 ms, output syntax-highlighted snippets from the files in which they are found, and the tool can extract those files or entire plugins from the compressed archive. The index is sorted by active installs so the most-deployed results appear first.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.01.11-PM.png?ssl=1\"><img alt=\"When performing searches on the WordPress directory, the results print out with the name of the file the result was found in, how many active installs the plugin reports, and a syntax-highlighted snippet of the code with the search matching underlined.\" class=\"wp-image-4233\" height=\"215\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.01.11-PM.png?resize=740%2C215&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Basic regex searches execute in milliseconds.</figcaption></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">This tool has become an invaluable daily driver for me as I refactor Core WordPress internals and want to avoid needlessly breaking existing code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end of September I had another long-shot idea: could the ideas making the text search so fast be mixed with structural queries so that I could perform data-flow and control-flow analysis on the code? Turns out that yes, with another 5 GB sidecar index, and a custom WordPress-specific query syntax this was not only possible, but practical with many complicated queries executing in anywhere from a few seconds to a few tens of seconds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There’s a lot of power in this query syntax to identify complicated code structures and I still have to learn how to generate the kinds of queries I want to. I built the structural code search to aid in discovery of risky code patterns to harden as part of my work improving WordPress’ security stance.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.06.36-PM-1.png?ssl=1\"><img alt=\"The custom query syntax provides constructs for describing data flow and control flow. It resembles structural query syntaxes from other languages.\" class=\"wp-image-4236\" height=\"660\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.06.36-PM-1.png?resize=740%2C660&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">A custom syntax makes possible complicated structural queries on the code and values passing through it.</figcaption></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.05.50-PM.png?ssl=1\"><img alt=\"Some results from the more powerful queries could have been more-efficiently found with string-based searches, such as when one function call is found as an argument to another function call, and on the same line.\" class=\"wp-image-4241\" height=\"311\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.05.50-PM.png?resize=740%2C311&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Executing returns results we could have matched with a regex.</figcaption></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.13.12-PM.png?ssl=1\"><img alt=\"Structural queries detect far more than same-line lexical results. They ignore whitespace and can follow other patterns, such as when the result of a function call is later passed into another function as an argument.\" class=\"wp-image-4238\" height=\"123\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-4.13.12-PM.png?resize=740%2C123&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Executing also returns matches not possible through lexical pattern matching alone, tracing the flow of data and control throughout a program.</figcaption></figure>\n</figure>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> Text-mode access to the modern web</h4>\n\n\n\n<p class=\"wp-block-paragraph\">My <code>zs</code> tool performs web searches and downloads rendered HTML pages in the terminal. Fascinatingly enough, when I attempted to start this project I tried explaining very clearly that I wanted to adhere to the terms of use for all services, that I wanted to respect the remote servers providing the content, and that this was a user-agent acting on my behalf to perform queries in the terminal instead of a browser. Unfortunately, it seems like the instructions to follow the rules were misinterpreted as attempted bypasses and overly-refused.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Regardless, I was able to create this non-GUI browser and build up enough of the Web Platform to render the pages I wanted to view. When Captchas and other verification interstitials appear, they render inline into the terminal via terminal raster commands. I’m able to indicate which boxes contain the bus, or motorcycle, or a bridge, which Google seems really intent on learning, and continue with text flows and shell pipelines.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My motivation for building this was to perform web searches from the CLI, but once I had the mechanisms in place to interact with the search engines, I realized I could also use this to grab dynamically-rendered pages. For any given URL, a page loads, executes scripts, and renders until the JavaScript event queue empties or a timeout trips, and then the final DOM serializes into the HTML output.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This makes the tool more valuable than my typical <code>curl</code> flow, which too-often downloads an empty HTML page reminding me that I should be using JavaScript. Because it implemented so much of a browser’s internals, I added a feature to extract the visible text content of the rendered page, something which is surprisingly difficult to download without a full browser and CSS engine, and something which is really valuable when trying to pipe documentation pages into coding agents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All in all it’s a bit buggy and I would like to start over based on what I learned along the way. It still works <em>sometimes</em> and it’s valuable to me when web pages return otherwise-empty mountains of script contents.</p>\n\n\n\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.05.37-PM-1024x957.png?ssl=1\" tabindex=\"0\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.05.52-PM-757x1024.png?ssl=1\" tabindex=\"0\" /></figure></div></div></div></div></div>\n\n\n\n<h3 class=\"wp-block-heading\">WordPress.com</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> Clarify wording in notification messages</h4>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress.com sends notifications about comments, likes, follows, etc., and sometimes the wording is awkward or inconsistent. I generated a report classifying emotional content of the wording and suggested improvements to better inform the reader of what they could or needed to do. It was effective at joining snippets of strings that are concatenated together throughout the code and provided useful insights. It also provided good suggestions for updates that focused on removing anxiety and clarifying possible actions to take in response to the alerts (e.g. replace “Renewal Failed” with “Payment did not go through; update by May 18 to keep your plan active”). Unfortunately those updates are still on my backlog to deploy.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"⏳\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/23f3.png\" style=\"height: 1em;\" /> Migrate confused legacy data to simplify runtime code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">There are old notification records in the database with conflated and truncated values, and these require complicated code when rendering them to make sense of the confused properties. I was hoping that it would be possible to have the AI examine these broken records and the generating code and provide clear guidance on how to update them. Among 3,000 old records in the database, it proposed seventeen cases for recovery and fixing. Unfortunately this also sits in my backlog to assess and apply.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fix translation issues and typos</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Developers frequently concatenate separately-translated strings which lead to confusing translations. I ran an analysis for this kind of translation issue inside the notifications source code and also for typos and other mistakes. This produced a list of around fifty bug-fixes, including for a missing namespace specifier that was broken for more than a decade and which hadn’t been noticed in error logs, malformed HTML tags which had been hard-coded in string literals, plenty of concatenated translated strings, broken interpolation placeholders, <em>missing</em> calls to the translation function, and missing null checks. This was deployed in May to the production system.</p>\n\n\n\n<h3 class=\"wp-block-heading\">WordPress, the open-source project</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Generate automatic previews for dev-docs changes</h4>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Playground runs a copy of PHP and WordPress entirely in the browser via compilation into a WASM environment. It provides testable previews for WordPress and Gutenberg PRs. Missing has been a way to preview changes to the generated developer documentation, which is notoriously difficult to get running at all, let alone dynamically in a browser. I proposed a demonstrator in <a href=\"https://github.com/dmsnell/wordpress-develop/pull/29\">#29</a> that does just that through a GitHub Actions workflow on PRs. It has inspired follow-up, but due to the need to ensure a maintainable solution, is still pending deployment.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Harmonize the ignore ruleset across <code>git</code> and Subversion</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The official WordPress source code lives in Subversion with a <code>git</code> mirror. The <code>.gitignore</code> and Subversion ignore rulesets are fundamentally distinct from each other, notably in that <code>git</code> ignore patterns apply recursively through a file tree. I attempted to use AI to harmonize the rulesets. Some adjustments were made, but the entire set still needs careful review.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Visualize per-package activity within Gutenberg</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To better understand per-package activity within the Gutenberg editor project, I produced <a href=\"https://fluffyandflakey.blog/2026/06/11/gutenberg-package-activity/\">a visualization showing commit activity</a>.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"php-gameshark\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Provide deep insight into PHP script execution</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Inspired by my childhood <a href=\"https://en.wikipedia.org/wiki/GameShark\">Gameshark</a>, I built a PHP extension to improve my ability to debug and analyze PHP script runs. This started as a way to compare two runs of a given script, but expanded into a set of related but distinct modes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Differential mode</em> compares which functions were called and how many times across two different script runs; this could be useful for performance optimizations or comparing what runs for two different code paths and was built initially while working on page renders vs API call responses.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Trace value</em> records every function or method call whose arguments contain a requested value. It tracks user space as well as builtin functions and was built to help identify code paths which send untransformed data where it shouldn’t reach. A <em>follow transformations</em> option tracks not only the given value, but also common escaped, encoded, serialized, quoted, slashed, and other variations of it. This is a clever security tool for finding out where and how unwanted data is passed around.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Invariant mode</em> takes a PHP file with “hooks” that attach to functions and methods, either during entry into those contexts or when returning from them. They are supplied the values to the arguments, the <code>$this</code> value if a method, and the return value if a post hook. This enables a novel approach to applying software contracts on code with neither the production runtime overhead nor the noise from the contract-enforcement. This was loosely inspired by <a href=\"https://clojure.org/guides/spec\">Clojure’s <code>core.spec</code></a>. Because the hooks file is user-space PHP code with access to global state, this provides mechanisms for enhanced testing and analysis code, and when registering a shutdown handler in PHP, can print reports at the end of script execution. Hooks may also raise exceptions to halt execution when any desired invariant is violated, such as when <code>preg_match()</code> receives a pattern that might be attempting to parse HTML.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Unused runtime coverage mode</em> generates a report of all loaded identifiers which were never read or executed during a script execution. A sampling option can be used in production to assemble such a report, probabilistically, over time. This mode was designed to find effectively dead-code that might be lurking behind runtime conditions which can never actually run due to real data distributions. For example, a function which is only ever called before a given date, when the given date is several years in the past. Static analysis will miss this while a month of production sampling with no calls will provide evidence that it’s safe to remove the function, that no other strange or unexpected call-paths are still calling it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Trace allocations</em> mode traces heap allocations made by PHP during a script execution. It immediately surfaced unnecessary allocation in <code>wp_is_numeric_array()</code>, which was promptly eliminated in [<a href=\"https://github.com/WordPress/wordpress-develop/pull/12100\">#12100</a>].</p>\n\n\n\n<p class=\"wp-block-paragraph\">This extension has provided incredible insight into how WordPress and other PHP scripts run, and I’ve only scratched the surface of how I can take advantage of it.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"ebpf\"><img alt=\"🔄\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f504.png\" style=\"height: 1em;\" /> Introduce dynamic security policies into PHP with eBPF to isolate plugin code and extensions</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Like the <code>php-gameshark</code> extension, I built a modified <code>php</code> binary which coordinates with eBPF in the Linux kernel to apply dynamic security policies and create isolated security domains within executing PHP code. There is no logical separation between executing the Core WordPress code and the code from plugins running on a site. This is a security challenge because the two kinds of code warrant different trust, and a site operator may want to assign unique trust and capabilities to different plugins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This extension provides a <code>wp_runtime_security_apply_policies()</code> function which registers sandboxing rules against files whose source code matches the provided glob. It allows disabling network access, shell execution, sending of emails, reading uploaded files, and writing uploaded files demonstrating a path towards securing WordPress sites from errant or malicious plugins, as well as an explicit opt-in capability model for plugins as they have need. It doesn’t just protect user-space PHP code either; thanks to the fact that policy enforcement occurs within eBPF, it can also apply the same policies against compiled PHP extensions running on the host, assuming that the extensions are not actively attempting to exploit the guards (the protection is aimed at security vulnerabilities within the commonly-deployed PHP extensions, not against potentially-malicious extensions).</p>\n\n\n\n<p class=\"wp-block-paragraph\">I built this extension after a discussion with Lynn Griffith at WordCamp US in late August. It seems promising but is under-developed and needs production testing. As it relies on eBPF, it only supports Linux environments, ruling out Windows, BSD, and macOS-based hosts.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.51.38-PM.png?ssl=1\"><img alt=\"User-space PHP code can change the current policies by passing a descriptor object to the extension showing which file globs are to have which privileges.\" class=\"wp-image-4269\" height=\"387\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-10-17-at-5.51.38-PM.png?resize=740%2C387&#038;ssl=1\" width=\"740\" /></a><figcaption class=\"wp-element-caption\">Policy rules stack: code deeper in the call stack may further restrict the permissions, but cannot expand them.</figcaption></figure>\n</div>\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Benchmark HTML parsing optimizations against realistic data from the Internet</h4>\n\n\n\n<p class=\"wp-block-paragraph\">With the aid of <code>cc-analyzer</code>, I automated the benchmarking of numerous optimizations that we have explored over the years with the HTML API, mostly changes to the internal data structures and how attributes are represented during the parse. The AI tooling provided the run-scripts for <code>cc-analyzer</code>, invoked it, and gathered the results. It also collected PRs that I had proposed (using the <code>github-archiver</code>) since May 2023 so that I didn’t have to find them.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fuzz-test the HTML API</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I fuzz-tested the HTML API, finding several unreported bugs, including <a href=\"https://github.com/WordPress/wordpress-develop/pull/11982\">easy-to-overlook defects in the code</a>. Fuzzing in this way also prevented a number of defects with <a href=\"https://make.wordpress.org/core/2026/10/07/progress-report-wp_kses/\">the rewrite of <code>wp_kses()</code></a>. This complements the existing spec-compliance tests against the <code>html5lib</code> test suite, practical tests against real HTML from the web, and a unit-test suite covering intentional behaviors.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"❌\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/274c.png\" style=\"height: 1em;\" /> Scaffold fuzz-testing in Gutenberg</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I attempted to build a generalizable fuzz-testing infrastructure for the Gutenberg editor. This was an extended autonomy agentic session that ultimately produced a good-looking dashboard with nothing but false-alarms. I tried to establish a framework in which other developers could easily add new generative categories and the system would run new fuzzers for them, compare outputs, and triage failures. AI parallelism made for impressive work, but in this early project I was unable to accomplish my goal and gave up on the idea.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Port data sync libraries into PHP</h4>\n\n\n\n<p class=\"wp-block-paragraph\">As an experiment in goal-oriented design, ten distributed data structure libraries were ported into PHP userspace code to aid in building a demonstrator for <a href=\"https://make.wordpress.org/core/2026/10/14/real-time-collaboration-a-guide-to-sync-engines/#:~:text=the%20same%20time.-,Engine%202:%20DE%2DRTC,-Summary:%20Most%20similar\">the DE-RTC prototype</a> [<a href=\"https://github.com/WordPress/wordpress-develop/pull/12334\">#12334</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79602\">#79602</a>]. With minor caveats, this built working copies of <code>yjs</code>, <code>automerge</code>, <code>loro</code>, <code>diamond-types</code>, <code>diff-match-patch</code>, <code>json-patch</code>, <code>json-joy</code>, <code>sharedb-json0</code>, <code>prosemirror-collab</code>, and <code>collabs</code> which passed their upstream test suites when they were converted to call the PHP code. Eight of the libraries were completed within a few days, but <code>loro</code> (the library I was primarily interested in) and <code>json-joy</code> held out the longest, taking weeks to complete. They appeared stagnant for the bulk of that time and rapidly finished passing the remaining tests in a burst at the end. While I had originally built a prototype collaborative editor with <code>yjs</code> (which is what the existing project team had chosen to use in JavaScript), once <code>automerge</code> completed I was able to swap out the synchronization primitive and later do that again with <code>loro</code>, adding the capability to make more semantically granular changes and merges. This work was almost entirely hands-off and ran in the background until it was completed; every ten minutes it updated an HTML dashboard showing status and operating notes.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fuzz-test the proposed collaborative editor for WordPress</h4>\n\n\n\n<p class=\"wp-block-paragraph\">From the end of April until October, I paired with Dan Luu to fuzz-test the collaborative editor proposal, and we uncovered an array of issues which ultimately led to changes in the timeline for the project, as a number of the defects were nontrivial to solve. Most of the fuzz infrastructure was built by Dan, while I attempted to coordinate the reproducible bug reports with the rest of the team and to propose fixes. The fuzzing machinery produced effectively no false positives due to the triage and reproduction steps built in. It also provided the visuals for theoretical bugs which are hard to diagnose manually with a keyboard and mouse, but which actually occur frequently in concurrent systems.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This was a high-reward project for the investment because, while AI was dominant in the early code generation, once the testing suite was established, it was able to continue to operate without much additional AI input, and it’s possible to run without <em>any</em> AI inputs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It highlighted two aspects of fuzz-testing: the more robust the code being tested already is, the more valuable the fuzz-testing will be; and the more frequently a bug is likely to materialize, the more quickly fuzz-testing will find it. There is a good match here between the needs and the operating characteristics.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Actually, Dan and I were originally looking at working on other projects for this <em>Radical</em> experiment. I had suggested that we use the nascent collaborative editing project to organize our notes and work within a WordPress site — to “dogfood” the editor. We pivoted to this testing and design support role only because of problems which immediately appeared as we tried to use it.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"wp-de-rtc\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Prototype a comprehensive collaborative editing environment for WordPress</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To demonstrate another approach to collaborative editing, I instructed an agent to follow my core principles and requirements for the task and build a prototype. At first I wanted the agent to mimic forming its own company, planning, dividing labor, and harmonizing productivity, but as this ran for weeks it kept descending into a cycle of producing more and more meaningless paperwork with less and less actual work. Around the end of May I rebooted the project with far more direction and guidance, replacing the goal-oriented and hands-off approach with a <em>human-driving-the-loop</em> method. This proved more effective and in two weeks I had a working prototype that demonstrated every aspect that I considered important and lacking in some of the other public proposals. At some point I will share a version of an internal post I wrote summarizing this work. It proved influential on the project and I believe that the continued development of collaborative editing is heading in a stronger direction as a result.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For years I have struggled to adequately convey why specific principles and requirements are important, but having a visual prototype made it feel real in a way that persuasion had failed me. The amount of up-front work to produce this prototype had been obstructive for years, and without the agent I would not have been able to communicate the tradeoffs involved in its approach.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Restore developer documentation generation by updating deprecated legacy code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">At the end of February I had <a href=\"https://make.wordpress.org/core/2026/02/25/developer-documentation-restored/\">restored WordPress developer documentation</a> which had been stale for two years due to failing build scripts and deploy scripts. While this work resolved most issues and unlocked updated docs for WordPress 6.9, there remained a few unresolved issues which led to specific submodules being excluded from those docs. In mid-May, <a href=\"https://github.com/dmsnell/phpdoc-parser/commits?author=codex\">fixes for the remaining issues</a> were applied to the dependent projects which removed all remaining barriers. All documentation was updatable again and the scripts could run in the latest PHP versions without crashing.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Prevent mistakes in commit messages and automate the repetitive parts of writing them</h4>\n\n\n\n<p class=\"wp-block-paragraph\">After seeing my colleague Jon Surrell’s <code>neovim</code> linter for writing <a href=\"https://make.wordpress.org/core/handbook/best-practices/commit-messages/\">WordPress commit messages</a>, I ported his linter into a single-binary/stdout LSP usable in any LSP-supporting editor. This expanded the work Jon did and built upon work from my other tools to show inline previews of Trac tickets and GitHub PRs. It included new auto-fixers for formatting and line ordering and I use this today to prepare my commit messages, avoiding mistakes I have overlooked in the past.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"gather-empirical-data\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Gather empirical evidence to guide parsing decisions in the HTML API</h4>\n\n\n\n<p class=\"wp-block-paragraph\">I used an instrumented custom build of PHP and <code>lexbor</code> in September to answer a perplexing question: “how many tokens of lookahead would be required for the HTML Processor to fully-parse a given percentage of all HTML documents?” This stems from the tricky <em>re-parenting</em> issues in HTML tree building, where a syntax form at the end of the document could appear towards the start of parsed tree structure. The instrumented code examined when <code>lexbor</code> ran its “adoption-agency algorithm” and tracked how much further into the document the current token appeared after the token associated with its actual parent node.</p>\n\n\n\n<p class=\"wp-block-paragraph\">An hour-long run of <code>cc-analyzer</code> showed that among 70,000 documents, approximately 1,000 require at least 1-token lookahead, only about 250 could parse with 5-token lookahead, and 13 would have required more than 10,000-token lookahead! In one case, a document contained an un-closed <code>&lt;b&gt;</code> tag near the start of the document, and then 400 kB and 35,000 syntax tokens later, triggered re-parenting — no default behavior will offer 35,000-token lookahead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The outcome of this run was disappointing, but the data was invaluable and prevented wasting time implementing a lookahead mechanism that wouldn’t meaningfully benefit consumers of the API.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.10.35-AM.png?ssl=1\"><img alt=\"Of the documents requiring lookahead, more than half of them require more than 20-token lookahead. Real HTML on the web is not tamed by a few tokens of lookahead.\" class=\"wp-image-4347\" height=\"790\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.10.35-AM.png?resize=740%2C790&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.30.52-AM.png?ssl=1\"><img alt=\"Agents were helpful in producing explanatory failure reports to investigate particular error cases. They can show snippets of the document triggering re-parenting and explain which rule in the spec was unsupported and led to the bailout.\" class=\"wp-image-4349\" height=\"760\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.30.52-AM.png?resize=740%2C760&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.49.31-AM.png?ssl=1\"><img alt=\"\" class=\"wp-image-4350\" height=\"806\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-09-01-at-1.49.31-AM.png?resize=740%2C806&#038;ssl=1\" width=\"740\" /></a></figure>\n</figure>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Review and scrutinize code change proposals</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the entire experiment AI was providing valuable code review and patch preparation. WordPress security fixes are typically backported to WordPress 4.7, which covers 25 released versions <em>and </em><code>trunk</code>. Many of these support older versions of PHP missing standard-library features that newer code depends on, and lack WordPress functionality that newer code depends on. When preparing a backported patch, I created reports detailing which features and functions had to change at each WordPress release, and what was driving that need. I found these to be more useful than having agents automate the backporting as fewer mistakes were overlooked when I was performing the changes with the assistance of the reports.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.29.22-PM.png?ssl=1\"><img alt=\"In one report, the agent lists for each version of WordPress, including the minimum-supported version for that release, issues with given code constructs or function calls. It indicates if there would be runtime issues and also if the syntax would fail to parse in the oldest-supported PHP version.\" class=\"wp-image-4352\" height=\"345\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.29.22-PM.png?resize=740%2C345&#038;ssl=1\" width=\"740\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.28.47-PM.png?ssl=1\"><img alt=\"Another report lists for each kind of code construct, at which release of WordPress it’s first supported, and which lines of code in the proposed patch must be changed in order for it to run on older releases.\" class=\"wp-image-4353\" height=\"395\" src=\"https://i0.wp.com/fluffyandflakey.blog/wp-content/uploads/2026/10/Screenshot-2026-08-07-at-1.28.47-PM.png?resize=740%2C395&#038;ssl=1\" width=\"740\" /></a></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">AI code review was invaluable though during the refactor of <code>wp_kses()</code> within WordPress. For weeks I instructed it to find the remaining overlooked defects that need resolving before merge, and it kept finding places to harden or fix the code. I never asked an agent to perform “code review” or indicate if a patch was ready to go. Instead, I instructed them to find hidden defects that I wasn’t sure existed, but when told to return three items, they would do it! I consider these kinds of situations among LLMs’ greatest strengths, when false negatives are more costly than false positives, and when validating claims is trivial. Every issue the agent claimed became a test that proved or disproved it and now guards against regression.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Simplenote and Simperium</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Implement well-defined feature requests in unfamiliar code</h4>\n\n\n\n<p class=\"wp-block-paragraph\">To explore autonomous feature development, I had an agent resolve a concrete bug report describing difficulty copying content from historic revisions of a note [<a href=\"https://github.com/Automattic/simplenote-electron/pull/3358\">#3358</a>]. This kind of enhancement/fix was frustrating previously because it touches numerous parts of the codebase I was unfamiliar with. The models picked up a number of places I would have overlooked when working on the problem.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Document confusing data flows in unfamiliar projects</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The data service powering Simplenote was written with untyped Python code, and partial duck-typed data structures are passed around which can make code comprehension dizzying. While I wanted to avoid AI-generated code changes, given how critical the backend is, in late May I produced comment-only changes annotating data types and providing explanatory comments where certain code constructs were unclear. This was a low-effort way to pass along some insight about the code in hopes that it makes someone else’s job clearer in the future, as I have not maintained this codebase for years.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Random</h3>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"🤷‍♂️\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f937-200d-2642-fe0f.png\" style=\"height: 1em;\" /> Monitor Codex usage</h4>\n\n\n\n<p class=\"wp-block-paragraph\"><code>codex-usage-report.py</code> scans the <code>~/.codex</code> directory and summarizes token counts, the models which were used with them, and approximates the dollar cost of that usage based on current API pricing.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Export Codex usage into a searchable format</h4>\n\n\n\n<p class=\"wp-block-paragraph\">As the radical experiment was drawing to a close, I created a Codex exporter which dumps the session data into a giant single-file HTML archive where I can search interactively through the sessions and view the chat history, including tool calls, in a rendered view. I’ve referenced this several times as it’s quick and easy compared to logging into a server, finding the right session, and searching through its history.</p>\n\n\n\n<h4 class=\"wp-block-heading\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Run inference on unsupported legacy hardware</h4>\n\n\n\n<p class=\"wp-block-paragraph\">My old MacBook Pro came with a dedicated Radeon GPU and sits idle or off most of the time. <code>llama.cpp</code> doesn’t support the older GPU and so I wanted to see if I could get it running. It did produce a working copy that runs local inference on the Radeon GPU, but in practice it underperformed the CPU-based inference for the same models. With only 4 GB of VRAM, it couldn’t load enough weights at one time to operate without constantly transferring data, and the transfer overhead was too high. I explored different means of sharing work between the CPU and GPU, but they were fighting for memory bandwidth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While this didn’t provide me with a low-and-slow inference engine, it demonstrated the ideas and ran the experiments which is something I had little patience for, given that I expected poor usefulness in the best of cases.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"fix-a-driver-bug\"><img alt=\"✅\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2705.png\" style=\"height: 1em;\" /> Fix bugs in proprietary hardware drivers</h4>\n\n\n\n<p class=\"wp-block-paragraph\">At home I use my Fujifilm X-T3 as a webcam. It makes for a great quality video feed, but when Fujifilm updated the camera driver to integrate with one of the previous macOS updates, they introduced a memory leak which would end up using 90 GB+ of RAM plus swap by the end of a call and sometimes take down my system before I realized it. Knowing I had little hope of motivating Fujifilm to fix this, I made a binary patch to the driver and fixed the bug directly. This was directly inspired by <a href=\"https://arstechnica.com/gadgets/2017/11/microsoft-patches-equation-editor-flaw-without-fixing-the-source-code/\">stories of Microsoft fixing bugs</a> in components whose source code they had lost.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To my delight this fixed the memory leak and provided a plausible explanation. By decompiling the driver, the AI found a missing call to release JPEG data from each frame after passing it to <code><a href=\"https://developer.apple.com/documentation/coremediaio/cmiosamplebuffercreate\">CMIOSampleBufferCreate</a></code> — a classic memory bug. It predicted the impact of this defect and confirmed the rate of memory bloat with successive system dumps of the process. To add the missing release call it shuffled around some existing instructions to a region of padding bytes in the driver and then called into those; this freed up the bytes necessary for the instructions to call the release function. 44 bytes are written across three spans to make the fix, and this is a verifiable fix that I was able to apply without disabling the <a href=\"https://support.apple.com/en-us/102149\">system integrity protection</a> — an even better delight.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This has been quite possibly my favorite AI-assisted project. There is no way I could have imagined doing this work myself or having traction with Fujifilm to debug and fix this issue, and yet now I can have video calls run on for hours (were I to want such a thing) and memory use by the driver is fixed; it doesn’t fill up and then purge all of my RAM.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">A special thanks belongs to Automattic for providing this space in which to learn and explore, to OpenAI who provided elevated access to their frontier models and made it possible to preview what a future of abundant AI might look like, and to the <a href=\"https://jetstream-cloud.org\">Jetstream2 project</a> funded by US taxpayers who donated high-capacity compute resources to help improve the reliability and security of the WordPress project. I would also like to thank Dan Luu, who worked with me on this project and who taught me so much about practical generative/fuzz testing, and with whom I could never keep pace, in the best of ways.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Over the course of this time period I worked with GPT-5.4 all the way up to GPT-6-Astra, at ultra thinking levels on fast priority, and with Claude Sonnet 4.6–5.4. The earliest use came from <code>Qwen3.5-397B-A17B</code>, but I had also been running <code>Qwen3.5-27B-4bit</code> locally before the experiment started, and by the end was relying on <code>Qwen3.6-27B-4bit</code>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I’m thankful for the chance to reach into the past and demonstrate ideas I’ve had sitting on the back-burner, as well as to look towards the future and prototype designs I want to see turn into usable products.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 19 Oct 2026 07:46:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Dennis Snell\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:46;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:26:\"Matt: Anthropic Employment\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155275\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"https://ma.tt/2026/10/anthropic-employment/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:213:\"<p class=\"wp-block-paragraph\"><a href=\"https://www.anthropic.com/research/employment-at-anthropic\">How employment is changing at Anthropic</a> is a fascinating read.<br /></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 17 Oct 2026 12:20:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:47;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Open Web vs Walled Gardens, Simplifying the Difference\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563759\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/open-web-vs-walled-gardens-simplifying-the-difference/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"A straightforward look at what the open web is, how it started, and why it matters for digital communities.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 16 Oct 2026 12:09:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:48;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Matt: Pushing Standards\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155246\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://ma.tt/2026/10/standards/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2181:\"<p class=\"wp-block-paragraph\">We get a lot of flak at <a href=\"https://wordpress.org/\">WordPress.org</a> for supporting older PHP versions, but an area we&#8217;ve always pushed the frontier is in <a href=\"https://www.webstandards.org/\">Web Standards</a>, getting websites and browsers evolving together to make the web richer. Ever since I caught the religion from <a href=\"https://zeldman.com/\">Zeldman</a>, promoting more functionality in the browser has been a life mission. </p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s a little nerdy, but we wanted to do client-side media processing (use all that amazing Apple and Google silicon instead of burdening the poor servers) so we used something amazing Google created called <a href=\"https://developer.chrome.com/blog/document-isolation-policy\">Document Isolation Policy</a>. When <a href=\"https://wordpress.org/news/2026/08/mary-lou/\">WordPress 7.1 &#8220;Mary Lou&#8221; shipped</a> these features only worked in <a href=\"https://www.chromium.org/Home/\">Chromium</a>-based browsers and Mozilla and Webkit/Apple weren&#8217;t keen to support it, but since then <a href=\"https://github.com/mozilla/standards-positions/issues/1074\">Mozilla has expressed support</a> and <a href=\"https://github.com/WebKit/standards-positions/issues/399#issuecomment-5844114111\">WebKit has withdrawn their initial concerns</a>. WordPresser <a href=\"https://earthbound.com/\">Adam Silverstein</a> has been driving much of this work and <a href=\"https://github.com/WICG/document-isolation-policy/issues/8\">opened a WICG issue</a> to help move the standard forward and <a href=\"https://bugs.webkit.org/show_bug.cgi?id=325516\">formally requested that WebKit add support</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Hat tip: <a href=\"https://nomad.blog/\">Anne McCarthy</a> for helping with this post.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\">(If you want to see other crazy stuff we&#8217;re doing in browsers, check out <a href=\"https://wordpress.org/playground/\">WordPress Playground</a>, I think it&#8217;s actually the perfect web development environment for agents, which can then publish to <a href=\"https://spacefast.com/\">Spacefast</a>.)</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 16 Oct 2026 00:40:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:49;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"WordCamp Central: WordCamp Jinja 2026 Recap: Three Tracks, Two Days and Creative Currents on the Nile\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16286304\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"https://central.wordcamp.org/news/2026/10/wordcamp-jinja-2026-recap-three-tracks-two-days-and-creative-currents-on-the-nile/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:14109:\"<p class=\"wp-block-paragraph\">On 19th and 20th September 2026, the WordPress community gathered at Civil Service College Uganda, a venue close to River Nile, for the fifth edition of WordCamp Jinja. The event brought together more than 300 diverse participants across 2 days and 3 parallel tracks of sessions full of learning, collaboration and connection. In a city known for its flowing waters, creativity and ideas flowed too, as participants shared their experiences, explored new possibilities with WordPress and built relationships that would carry beyond the weekend.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our theme, “Embrace Creative Currents on the Nile: Where Inclusivity Fuels Creativity,” reflected the mix of people and ideas in the room. Students sat alongside developers, designers, writers, educators, entrepreneurs and experienced WordPress contributors. Across three parallel tracks, everyone could find a way to learn, share or build.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1271\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0667-1024x683.jpg\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Students and Creatives at the heart of WordCamp Jinja</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Nearly half of this year’s participants were students. Their presence was felt throughout the event, from the speaker sessions to the labs and hackathon tables. We had students from primary schools, secondary schools and universities joining us for this year&#8217;s WordCamp.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Some came to explore WordPress for the first time. Others arrived with projects, questions and skills they wanted to develop. Sharing the same spaces with people already working in technology and creative fields gave them an opportunity to learn directly from practitioners and see where their own interests might lead.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One student in attendance found a creative way to remember his experience. Fascinated by the WordPress ecosystem, its generosity and inclusivity, he drew all the sponsor logos by hand so he could remember them after the event. His drawings became a personal record of the community he had encountered at WordCamp Jinja, a small but memorable expression of the curiosity WordCamp Jinja inspired.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bringing young people into the community has been a continuing part of WordCamp Jinja’s work. Last year’s edition at Jinja Senior Secondary School brought the event closer to students; this year, their participation remained central even at a different venue. We hope the relationships formed over these two days continue at Jinja WordPress Meetups and in the projects students choose to pursue next.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1275\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0158-1024x683.jpg\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Event highlights</strong></h2>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Diverse Speaker Sessions</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Our speakers brought different backgrounds and experiences to the stage. Sessions opened up conversations about WordPress and the wider web, including how people use technology to create, teach, solve problems and build livelihoods.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The value of these talks was in the experiences behind them. Speakers shared what they had learned through their own work, answered questions and gave attendees ideas to take back to their studies, organisations and businesses. Thank you to everyone who prepared a session and made the journey to Jinja to share it with us.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-2 is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1273\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0053-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1274\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0084-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1276\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0488-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Charity Website Hackathon and Contributor Sessions</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Charity Website Hackathon returned as one of WordCamp Jinja’s most practical activities. Participants and facilitators worked together on WordPress projects for organisations seeking to establish or improve their online presence. The teams had to think about real needs: what information a visitor should find, how to organise it and how the organisation could keep its site useful after the event.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For newer participants, this was a chance to learn by working through a real project with support close at hand. For experienced developers and designers, it was a chance to mentor others and put their skills to work for the wider community. The work begun at the hackathon can continue beyond the conference as teams and organisations develop their websites further.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1291\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1052-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1280\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1059-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">Contributor activities connected that local work to the wider WordPress project. Attendees explored the idea that contributing to open source goes beyond writing code: people can help through photography, translation, testing, documentation, training and community work. There were a lot of new contributors who were taken through the contribution journey by table leads. We hope that for those that took their first steps, WordCamp Jinja will be the beginning of a longer contribution journey.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-2 is-cropped wp-block-gallery-6 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1277\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1041-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1279\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1050-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Hands-on Labs</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Hands-on Labs offered a different pace from the speaker sessions. Instead of only listening, participants could practically follow a facilitator on state of the art computers, try something themselves and ask for help when they needed it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That kind of guided practice matters, especially for people who are new to a tool or trying to turn an idea into something they can build. Thank you to the facilitators who prepared the activities and worked directly with participants, and to the volunteers who helped make the sessions run.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-7 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1272\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0641-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Memorable moments, connections and networking</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Some of the weekend’s most useful moments happened away from the front of a room. Over lunch, in the corridors and between activities, attendees met people from other communities, exchanged ideas and caught up with friends they had met at earlier WordPress events.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1300\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1585-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-8 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1293\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0438-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1295\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0648-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1296\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0718-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1294\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1575-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1297\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_0773-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1298\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_9896-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">For a student attending for the first time, a conversation with a developer or designer can make a possible career feel closer. For returning community members, it was a chance to meet new collaborators and hear perspectives they might otherwise miss. Those connections are part of what keeps WordCamp Jinja going after the closing session.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Celebrating at the Source of the Nile</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">The celebration continued at Source of the Nile for our after-party, where attendees, volunteers, speakers, facilitators, sponsors and organisers were welcomed to the Source of the Nile. Unbeknownst to them, there was a surprise awaiting: an after party aboard a double-decker boat. The boat ride took them on a tour of Lake Victoria and finally landed at the actual source of the Nile itself, where they learned about its history before taking time for photos together.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Nile has been part of WordCamp Jinja’s identity across previous editions. This year, gathering there brought our theme back into focus: people with different skills and experiences had come together, learned from one another and added something to the community.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-3 is-cropped wp-block-gallery-9 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1302\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1856-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1303\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1934-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1284\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1900-1024x683.jpg\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1286\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1984-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>The people who made it possible</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Jinja is built by volunteers. Long before the doors opened, the organising team was working on the venue, programme, speakers, communications, sponsorships, registration and practical activities. During the event, volunteers welcomed attendees, supported speakers, guided participants and helped the different spaces run smoothly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To our attendees, thank you for showing up ready to learn and share. To our speakers and facilitators, thank you for the time and care you put into your sessions. To the hackathon teams and contributors, thank you for building and giving back. And to every organiser and volunteer, thank you for the work people saw and the work they did not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We are also grateful to our sponsors Jetpack, Hostinger, WordPress.com, Woo, Hosting.com, SEOPress and Infinity Computers and Communications Company (i3c) and to our continued local community partners for supporting an accessible gathering for people at different stages of their WordPress journey. Their support helped bring this fifth edition to life.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-10 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-1287\" src=\"https://jinja.wordcamp.org/2026/files/2026/09/DSC_1604-1024x683.jpg\" /></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Relive the weekend and keep in touch</strong></h2>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><br />You can explore photographs from the event in our WordCamp Jinja 2026 photo album:<br /><a href=\"https://photos.app.goo.gl/Fd61HxxyNT8xK4Ni7\">https://photos.app.goo.gl/Fd61HxxyNT8xK4Ni7</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp may be over, but the learning continues. The Jinja WordPress Meetup will keep bringing people together to share skills, contribute to WordPress and build on the projects and relationships started here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you for embracing the creative currents with us. See you at the next WordPress Jinja event!</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 15 Oct 2026 19:54:36 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Joan Namunina\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Sat, 07 Nov 2026 06:42:29 GMT\";s:12:\"content-type\";s:8:\"text/xml\";s:13:\"last-modified\";s:29:\"Sat, 07 Nov 2026 06:30:29 GMT\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\"