--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-11-07 04:40:14','2026-11-07 04:40:14','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-11-07 04:40:14','2026-11-07 04:40:14','',0,'http://prime-cleaning-service.local/?p=1',0,'post','',1),(2,1,'2026-11-07 04:40:14','2026-11-07 04:40:14','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://prime-cleaning-service.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-11-07 04:40:14','2026-11-07 04:40:14','',0,'http://prime-cleaning-service.local/?page_id=2',0,'page','',0),(3,1,'2026-11-07 04:40:14','2026-11-07 04:40:14','\n<div style=\"max-width: 850px;margin: 0 auto;padding: 2rem 0\">\n    <div style=\"background: #fff7ed;border-left: 4px solid #f97316;padding: 1rem 1.25rem;margin-bottom: 2rem;border-radius: 4px\">\n        <strong style=\"color: #9a3412\">Draft for Business Review:</strong>\n        <span style=\"color: #7c2d12;font-size: 0.95rem\">This privacy policy is a provisional draft prepared for review by Prime Domestic &amp; Cleaning Services in accordance with the Australian Privacy Principles (APPs). It should be reviewed and finalised prior to live customer transactions.</span>\n    </div>\n\n    <h2 style=\"color: #1e3a5f\">1. Collection of Personal Information</h2>\n    <p style=\"color: #475569;line-height: 1.6\">\n        Prime Domestic &amp; Cleaning Services collects personal information submitted voluntarily by visitors requesting cleaning price estimates or booking cleaning services. This information may include your name, email address, phone number, residential or commercial address, and service preferences.\n    </p>\n\n    <h2 style=\"color: #1e3a5f\">2. Use of Information</h2>\n    <p style=\"color: #475569;line-height: 1.6\">\n        Information collected through this website is used solely to:\n    </p>\n    <ul style=\"color: #475569;line-height: 1.7;padding-left: 1.25rem\">\n        <li>Calculate accurate cleaning price estimates and evaluate service area coverage.</li>\n        <li>Contact you regarding your quotation request, scheduling availability, and booking confirmations.</li>\n        <li>Deliver contracted domestic and commercial cleaning services.</li>\n    </ul>\n\n    <h2 style=\"color: #1e3a5f\">3. Non-Disclosure &amp; Security</h2>\n    <p style=\"color: #475569;line-height: 1.6\">\n        We do not sell, rent, or trade your personal information to third parties. Customer records are stored securely within our authenticated administrative systems and accessed only by authorised personnel for operational purposes.\n    </p>\n\n    <h2 style=\"color: #1e3a5f\">4. Payment Security</h2>\n    <p style=\"color: #475569;line-height: 1.6\">\n        This demonstration website does not process online credit card payments or retain banking credentials. Payment arrangements are confirmed directly with clients upon agreement of services.\n    </p>\n\n    <h2 style=\"color: #1e3a5f\">5. Contact Regarding Privacy</h2>\n    <p style=\"color: #475569;line-height: 1.6\">\n        For queries concerning personal information handling or to request updates to your records, please contact:\n        <br>\n        <strong>Prime Domestic &amp; Cleaning Services</strong><br>\n        Base: Malvern East VIC 3145<br>\n        Email: <a href=\"mailto:info@example.com\">info@example.com (Demo placeholder)</a>\n    </p>\n</div>\n','Privacy Policy','','publish','closed','open','','privacy-policy','','','2026-11-07 11:52:05','2026-11-07 11:52:05','',0,'http://prime-cleaning-service.local/?page_id=3',5,'page','',0),(4,0,'2026-11-07 04:46:14','2026-11-07 04:46:14','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-11-07 04:46:14','2026-11-07 04:46:14','',0,'http://prime-cleaning-service.local/navigation/',0,'wp_navigation','',0),(5,1,'2026-11-07 06:42:11','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2026-11-07 06:42:11','0000-00-00 00:00:00','',0,'http://prime-cleaning-service.local/?p=5',0,'post','',0),(6,0,'2026-11-07 11:52:05','2026-11-07 11:52:05','\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding:0;margin:0\">\n    <!-- HERO SECTION -->\n    <div style=\"background: radial-gradient(circle at 80% 20%, rgba(13, 148, 136, 0.22) 0%, transparent 45%), linear-gradient(135deg, #0a1628 0%, #162a45 60%, #0d283e 100%);color: #ffffff;padding: 5rem 1.5rem 4.5rem;text-align: center;position: relative\">\n        <div style=\"max-width: 860px;margin: 0 auto\">\n            <div style=\"display: inline-flex;align-items: center;gap: 0.5rem;padding: 0.4rem 1rem;border-radius: 9999px;font-size: 0.82rem;font-weight: 800;letter-spacing: 0.08em;text-transform: uppercase;color: #5eead4;margin-bottom: 1.5rem\">\n                <span style=\"display:inline-block;width:8px;height:8px;border-radius:50%;background:#2dd4bf;box-shadow:0 0 8px #2dd4bf\"></span>\n                Melbourne Domestic &amp; Commercial Cleaning Specialists &bull; Malvern East Hub\n            </div>\n            \n            <h1 style=\"font-size: 3.25rem;font-weight: 800;color: #ffffff;letter-spacing: -0.035em;line-height: 1.15;margin: 0 0 1.25rem 0\">\n                High-Standard Cleaning for Melbourne Homes &amp; Workplaces\n            </h1>\n            \n            <p style=\"font-size: 1.22rem;color: #cbd5e1;line-height: 1.65;margin: 0 auto 2.25rem;max-width: 720px\">\n                Operating from Malvern East (3145), Prime Domestic &amp; Cleaning Services delivers dependable domestic maintenance, detailed deep cleans, agent-ready bond vacates, and commercial office cleaning.\n            </p>\n            \n            <div style=\"display: flex;gap: 1.15rem;justify-content: center;flex-wrap: wrap;margin-bottom: 2rem\">\n                <a href=\"http://prime-cleaning-service.local/get-a-quote/\" class=\"pce-btn-primary\" style=\"font-size: 1.05rem;padding: 0.95rem 2.25rem\">\n                    Instant Price Estimator &rarr;\n                </a>\n                <a href=\"http://prime-cleaning-service.local/services/\" class=\"pce-btn-secondary\" style=\"color: #ffffff !important;font-size: 1.05rem;padding: 0.95rem 2.25rem\">\n                    Explore Services Scope\n                </a>\n            </div>\n\n            <div style=\"display: inline-flex;align-items: center;gap: 0.5rem;padding: 0.4rem 1.15rem;border-radius: 9999px;font-size: 0.82rem;color: #94a3b8\">\n                <span>✦</span> Demonstration website &mdash; Sample rates and provisional service scopes for project review.\n            </div>\n        </div>\n    </div>\n\n    <!-- VALUE METRICS STRIP -->\n    <div style=\"background: #ffffff;border-bottom: 1px solid #e2e8f0;padding: 1.75rem 1.5rem\">\n        <div style=\"max-width: 1140px;margin: 0 auto;display: grid;grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));gap: 1.5rem;text-align: left\">\n            <div style=\"display: flex;align-items: flex-start;gap: 0.85rem\">\n                <div style=\"width: 40px;height: 40px;border-radius: 8px;background: #f0fdfa;border: 1px solid #99f6e4;color: #0d9488;display: flex;align-items: center;justify-content: center;font-size: 1.2rem;flex-shrink: 0\">⚡</div>\n                <div>\n                    <strong style=\"color: #0f172a;font-size: 0.95rem;display: block\">Instant Online Pricing</strong>\n                    <span style=\"color: #64748b;font-size: 0.85rem;line-height: 1.4;display: block\">Get immediate transparent AUD estimates in under 60 seconds.</span>\n                </div>\n            </div>\n\n            <div style=\"display: flex;align-items: flex-start;gap: 0.85rem\">\n                <div style=\"width: 40px;height: 40px;border-radius: 8px;background: #f0fdfa;border: 1px solid #99f6e4;color: #0d9488;display: flex;align-items: center;justify-content: center;font-size: 1.2rem;flex-shrink: 0\">📍</div>\n                <div>\n                    <strong style=\"color: #0f172a;font-size: 0.95rem;display: block\">Malvern East Base</strong>\n                    <span style=\"color: #64748b;font-size: 0.85rem;line-height: 1.4;display: block\">Focused coverage across Melbourne inner south-east &amp; eastern suburbs.</span>\n                </div>\n            </div>\n\n            <div style=\"display: flex;align-items: flex-start;gap: 0.85rem\">\n                <div style=\"width: 40px;height: 40px;border-radius: 8px;background: #f0fdfa;border: 1px solid #99f6e4;color: #0d9488;display: flex;align-items: center;justify-content: center;font-size: 1.2rem;flex-shrink: 0\">🛡️</div>\n                <div>\n                    <strong style=\"color: #0f172a;font-size: 0.95rem;display: block\">Clear Task Checklists</strong>\n                    <span style=\"color: #64748b;font-size: 0.85rem;line-height: 1.4;display: block\">Detailed room-by-room specifications for routine, vacate &amp; offices.</span>\n                </div>\n            </div>\n\n            <div style=\"display: flex;align-items: flex-start;gap: 0.85rem\">\n                <div style=\"width: 40px;height: 40px;border-radius: 8px;background: #f0fdfa;border: 1px solid #99f6e4;color: #0d9488;display: flex;align-items: center;justify-content: center;font-size: 1.2rem;flex-shrink: 0\">📅</div>\n                <div>\n                    <strong style=\"color: #0f172a;font-size: 0.95rem;display: block\">Flexible Scheduling</strong>\n                    <span style=\"color: #64748b;font-size: 0.85rem;line-height: 1.4;display: block\">Weekly and fortnightly discounts (up to 15% off) or casual visits.</span>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"4.5rem\",\"bottom\":\"4.5rem\"}}}} -->\n<div class=\"wp-block-group\" style=\"max-width: 1160px;margin: 0 auto;padding: 4.5rem 1.5rem\">\n    <div style=\"text-align: center;max-width: 680px;margin: 0 auto 3.5rem\">\n        <span class=\"pce-badge\">Our Cleaning Solutions</span>\n        <h2 style=\"font-size: 2.35rem;color: #0f172a;letter-spacing: -0.025em;margin: 0.5rem 0 0.75rem\">Structured Services for Homes &amp; Workplaces</h2>\n        <p style=\"color: #64748b;font-size: 1.05rem;line-height: 1.6\">\n            Every property has distinct priorities. Choose a specialized service below to review detailed inclusions and calculate your estimate.\n        </p>\n    </div>\n\n    <div style=\"display: grid;grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));gap: 1.75rem\">\n        <!-- Card 1 -->\n        <div class=\"pce-card\">\n            <span class=\"pce-badge\" style=\"background:#ccfbf1;color:#0f766e\">Domestic Maintenance</span>\n            <h3 style=\"font-size: 1.35rem;color: #0f172a;margin: 0.75rem 0 0.5rem\">Regular Home Cleaning</h3>\n            <p style=\"color: #64748b;font-size: 0.94rem;line-height: 1.55;margin-bottom: 1.25rem\">\n                Scheduled weekly or fortnightly maintenance visits keeping kitchens, bathrooms, living areas, and floors spotless on auto-pilot.\n            </p>\n            <div style=\"border-top: 1px solid #f1f5f9;padding-top: 1rem;margin-bottom: 1.25rem\">\n                <div style=\"font-size: 0.85rem;color: #0f766e;font-weight: 700;margin-bottom: 0.5rem\">Key Inclusions:</div>\n                <ul style=\"color: #475569;font-size: 0.88rem;line-height: 1.6;margin: 0;padding-left: 1.15rem\">\n                    <li>Bathrooms scrubbed &amp; sanitised</li>\n                    <li>Kitchen benches, stove &amp; sink polished</li>\n                    <li>Full vacuuming &amp; hard-floor mopping</li>\n                </ul>\n            </div>\n            <div style=\"display:flex;justify-content:space-between;align-items:center;border-top: 1px solid #f1f5f9;padding-top: 1rem\">\n                <span style=\"font-weight:700;color:#0d9488;font-size:0.95rem\">Save up to 15%</span>\n                <a href=\"http://prime-cleaning-service.local/services/regular-home-cleaning/\" style=\"color:#0f766e;font-weight:700;font-size:0.92rem;text-decoration:none\">View Scope &rarr;</a>\n            </div>\n        </div>\n\n        <!-- Card 2 -->\n        <div class=\"pce-card\">\n            <span class=\"pce-badge\" style=\"background:#e0f2fe;color:#0369a1\">Intensive Restorative</span>\n            <h3 style=\"font-size: 1.35rem;color: #0f172a;margin: 0.75rem 0 0.5rem\">Deep Cleaning</h3>\n            <p style=\"color: #64748b;font-size: 0.94rem;line-height: 1.55;margin-bottom: 1.25rem\">\n                Top-to-bottom intensive overhaul targeting built-up grime, scale, skirtings, door frames, and high-touch points across the property.\n            </p>\n            <div style=\"border-top: 1px solid #f1f5f9;padding-top: 1rem;margin-bottom: 1.25rem\">\n                <div style=\"font-size: 0.85rem;color: #0369a1;font-weight: 700;margin-bottom: 0.5rem\">Key Inclusions:</div>\n                <ul style=\"color: #475569;font-size: 0.88rem;line-height: 1.6;margin: 0;padding-left: 1.15rem\">\n                    <li>Skirting boards &amp; architraves hand-wiped</li>\n                    <li>Grout, tiles &amp; limescale descaling</li>\n                    <li>Cupboard exteriors &amp; rangehood detail</li>\n                </ul>\n            </div>\n            <div style=\"display:flex;justify-content:space-between;align-items:center;border-top: 1px solid #f1f5f9;padding-top: 1rem\">\n                <span style=\"font-weight:700;color:#0369a1;font-size:0.95rem\">Spring / Detail</span>\n                <a href=\"http://prime-cleaning-service.local/services/deep-cleaning/\" style=\"color:#0369a1;font-weight:700;font-size:0.92rem;text-decoration:none\">View Scope &rarr;</a>\n            </div>\n        </div>\n\n        <!-- Card 3 -->\n        <div class=\"pce-card\">\n            <span class=\"pce-badge\" style=\"background:#ffedd5;color:#c2410c\">Tenancy Handover</span>\n            <h3 style=\"font-size: 1.35rem;color: #0f172a;margin: 0.75rem 0 0.5rem\">End-of-Lease Cleaning</h3>\n            <p style=\"color: #64748b;font-size: 0.94rem;line-height: 1.55;margin-bottom: 1.25rem\">\n                Vacate cleaning aligned with Melbourne real estate agent checklists to assist tenants and landlords with tenancy bond handover.\n            </p>\n            <div style=\"border-top: 1px solid #f1f5f9;padding-top: 1rem;margin-bottom: 1.25rem\">\n                <div style=\"font-size: 0.85rem;color: #c2410c;font-weight: 700;margin-bottom: 0.5rem\">Key Inclusions:</div>\n                <ul style=\"color: #475569;font-size: 0.88rem;line-height: 1.6;margin: 0;padding-left: 1.15rem\">\n                    <li>Oven interior &amp; rangehood degreased</li>\n                    <li>Cupboards &amp; drawers wiped inside &amp; out</li>\n                    <li>Window glass, tracks &amp; spot wall cleaning</li>\n                </ul>\n            </div>\n            <div style=\"display:flex;justify-content:space-between;align-items:center;border-top: 1px solid #f1f5f9;padding-top: 1rem\">\n                <span style=\"font-weight:700;color:#c2410c;font-size:0.95rem\">Bond Checklists</span>\n                <a href=\"http://prime-cleaning-service.local/services/end-of-lease-cleaning/\" style=\"color:#c2410c;font-weight:700;font-size:0.92rem;text-decoration:none\">View Scope &rarr;</a>\n            </div>\n        </div>\n\n        <!-- Card 4 -->\n        <div class=\"pce-card\">\n            <span class=\"pce-badge\" style=\"background:#f3e8ff;color:#7e22ce\">Workplace &amp; Commercial</span>\n            <h3 style=\"font-size: 1.35rem;color: #0f172a;margin: 0.75rem 0 0.5rem\">Office Cleaning</h3>\n            <p style=\"color: #64748b;font-size: 0.94rem;line-height: 1.55;margin-bottom: 1.25rem\">\n                Commercial workspace cleaning for Melbourne consulting rooms, corporate suites, studios, and medical practices billed on hourly duration.\n            </p>\n            <div style=\"border-top: 1px solid #f1f5f9;padding-top: 1rem;margin-bottom: 1.25rem\">\n                <div style=\"font-size: 0.85rem;color: #7e22ce;font-weight: 700;margin-bottom: 0.5rem\">Key Inclusions:</div>\n                <ul style=\"color: #475569;font-size: 0.88rem;line-height: 1.6;margin: 0;padding-left: 1.15rem\">\n                    <li>Workstations, desks &amp; contact points</li>\n                    <li>Staff kitchen, t